/* ============================================================================
   SP 1. reclamo.sp_congelar_modulo

   Regla R1. Toma el tonelaje conformado desde modulos_turnos y el volumen y
   densidad desde disponible_rotopalas, y los congela.

   Un modulo ya congelado NO se puede volver a congelar sin @Forzar = 1, y esa
   accion queda registrada en la observacion.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_congelar_modulo]
(
    @CampañaId          int,
    @ModuloId           int,
    @PadId              int,
    @ParcelaId          int          = NULL,
    @FechaConformacion  date         = NULL,
    @Forzar             bit          = 0,
    @Observacion        nvarchar(1000) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @CampañaId IS NULL OR @ModuloId IS NULL OR @PadId IS NULL
        THROW 60001, 'Debe informar campana, modulo y PAD.', 1;

    DECLARE @Existe int =
    (
        SELECT COUNT(*)
        FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId
    );

    IF @Existe > 0 AND @Forzar = 0
        THROW 60002,
              'El modulo ya esta congelado. Use @Forzar = 1 y explique el motivo en @Observacion.', 1;

    IF @Existe > 0 AND @Forzar = 1 AND @Observacion IS NULL
        THROW 60003,
              'Recongelar un modulo exige @Observacion con el motivo.', 1;

    /* ---- Base oficial: disponible_rotopalas -------------------------------
       CORRECCION 30-07-2026. El diseno original tomaba el TMS de la suma de
       modulos_turnos. El script 00 mostro que esa suma esta un orden por
       encima del valor de disponible_rotopalas, que es ademas el que usa la
       hoja "Disponible para rotopalas" del libro de ripios.
       disponible_rotopalas manda; modulos_turnos queda como contraste. */
    DECLARE @Tms      decimal(30,12);
    DECLARE @M3       decimal(30,12);
    DECLARE @Densidad decimal(30,12);

    SELECT TOP (1)
        @Tms      = CAST(dr.[tms]        AS decimal(30,12)),
        @M3       = CAST(dr.[m3_totales] AS decimal(30,12)),
        @Densidad = CAST(dr.[densidad]   AS decimal(30,12))
    FROM [inventar_SpcHidr].[disponible_rotopalas] dr
    WHERE dr.[campaña_id] = @CampañaId
      AND dr.[modulo_id]  = @ModuloId;

    IF @Tms IS NULL OR @Tms <= 0
        THROW 60004,
              'disponible_rotopalas no tiene tms para esa campana y modulo.', 1;

    IF @M3 IS NULL OR @M3 <= 0
        THROW 60005,
              'disponible_rotopalas no tiene m3_totales para esa campana y modulo.', 1;

    /* Si la densidad declarada no viene o es cero, se deriva del cociente. */
    IF COALESCE(@Densidad, 0) <= 0
        SET @Densidad = @Tms / @M3;

    /* Contraste con modulos_turnos, solo informativo. */
    DECLARE @TmsTurnos decimal(30,12) =
    (
        SELECT SUM(COALESCE(mt.[TMS], 0))
        FROM [inventar_SpcHidr].[modulos_turnos] mt
        WHERE mt.[campaña_id] = @CampañaId
          AND mt.[modulo_id]  = @ModuloId
    );

    IF @TmsTurnos IS NOT NULL AND @Tms > 0
       AND ABS(@TmsTurnos - @Tms) * 100.0 / @Tms > 10
        PRINT '        AVISO: modulos_turnos suma ' + CAST(@TmsTurnos AS varchar(40))
            + ' TMS y disponible_rotopalas informa ' + CAST(@Tms AS varchar(40))
            + '. Se congela con disponible_rotopalas.';

    /* Parcela y PAD se derivan de la jerarquia real pad > parcela > modulo,
       confirmada en el script 00 seccion 4. */
    IF @ParcelaId IS NULL
        SELECT @ParcelaId = md.id_parcela
        FROM [inventar_SpcHidr].[modulo] md
        WHERE md.id_modulo = @ModuloId;

    DECLARE @ModuloNumero int =
    (
        SELECT TOP (1) md.numero
        FROM [inventar_SpcHidr].[modulo] md
        WHERE md.id_modulo = @ModuloId
    );

    /* El numero de modulo debe caer dentro del rango fisico del PAD.
       Oxido: 32 parcelas x 2 modulos = 1 a 64.
       Sulfuro: 28 parcelas x 5 modulos = 1 a 140. */
    DECLARE @Min int, @Max int, @PadNombre varchar(40);
    SELECT @Min = tp.modulo_numero_min,
           @Max = tp.modulo_numero_max,
           @PadNombre = tp.nombre
    FROM [reclamo].[topologia_pad] tp
    WHERE tp.pad_id = @PadId;

    IF @Min IS NULL
        THROW 60006,
              'No hay topologia definida para ese PAD. Revise reclamo.topologia_pad.', 1;

    IF @ModuloNumero IS NOT NULL AND @ModuloNumero NOT BETWEEN @Min AND @Max
    BEGIN
        DECLARE @Msg nvarchar(300) =
            N'El modulo ' + CAST(@ModuloNumero AS nvarchar(10))
            + N' esta fuera del rango del ' + @PadNombre
            + N' (' + CAST(@Min AS nvarchar(10)) + N' a ' + CAST(@Max AS nvarchar(10)) + N').';
        THROW 60007, @Msg, 1;
    END;

    IF @Existe > 0
    BEGIN
        UPDATE [reclamo].[modulo_congelado]
        SET pad_id              = @PadId,
            parcela_id          = @ParcelaId,
            modulo_numero       = @ModuloNumero,
            fecha_conformacion  = COALESCE(@FechaConformacion, fecha_conformacion),
            fecha_congelamiento = CAST(SYSDATETIME() AS date),
            tms_conformado      = @Tms,
            m3_totales          = @M3,
            densidad_oficial    = @Densidad,
            fuente              = 'DISPONIBLE_ROTOPALAS',
            metodo              = 'RECONGELADO_FORZADO',
            usuario_registro    = SUSER_SNAME(),
            fecha_registro      = SYSDATETIME(),
            observacion         = @Observacion
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId;

        PRINT 'Modulo RECONGELADO. Campana ' + CAST(@CampañaId AS varchar)
            + ' modulo ' + CAST(@ModuloId AS varchar);
    END
    ELSE
    BEGIN
        INSERT INTO [reclamo].[modulo_congelado]
        (
            [campaña_id], pad_id, parcela_id, modulo_id, modulo_numero,
            fecha_conformacion, fecha_congelamiento,
            tms_conformado, m3_totales, densidad_oficial,
            fuente, metodo, estado, observacion
        )
        VALUES
        (
            @CampañaId, @PadId, @ParcelaId, @ModuloId, @ModuloNumero,
            COALESCE(@FechaConformacion, CAST(SYSDATETIME() AS date)),
            CAST(SYSDATETIME() AS date),
            @Tms, @M3, @Densidad,
            'DISPONIBLE_ROTOPALAS',
            'TMS_Y_VOLUMEN_DE_DISPONIBLE_ROTOPALAS',
            'CONGELADO', @Observacion
        );

        PRINT 'Modulo CONGELADO. Campana ' + CAST(@CampañaId AS varchar)
            + ' modulo ' + CAST(@ModuloId AS varchar)
            + ' TMS ' + CAST(@Tms AS varchar(40))
            + ' m3 '  + CAST(@M3 AS varchar(40));
    END;

    SELECT *
    FROM [reclamo].[modulo_congelado]
    WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId;
END;

CREATE   PROCEDURE inventar_SpcHidr.sp_rep_log_validacion_decision
    @run_id UNIQUEIDENTIFIER,
    @caso_id INT,
    @decision VARCHAR(20),
    @usuario_validacion NVARCHAR(128) = NULL,
    @resumen_json NVARCHAR(MAX) = NULL,
    @observacion NVARCHAR(1000) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @fecha_inicio DATE = NULL;
    DECLARE @fecha_fin DATE = NULL;

    DECLARE @periodo TABLE (fecha_inicio DATE, fecha_fin DATE);

    INSERT INTO @periodo(fecha_inicio, fecha_fin)
    EXEC inventar_SpcHidr.sp_rep_get_periodo_caso @caso_id = @caso_id;

    SELECT TOP 1
        @fecha_inicio = fecha_inicio,
        @fecha_fin = fecha_fin
    FROM @periodo;

    INSERT INTO inventar_SpcHidr.rep_prod_validacion_log
    (
        run_id,
        caso_id,
        fecha_inicio,
        fecha_fin,
        decision,
        usuario_validacion,
        resumen_json,
        observacion
    )
    VALUES
    (
        @run_id,
        @caso_id,
        @fecha_inicio,
        @fecha_fin,
        @decision,
        @usuario_validacion,
        @resumen_json,
        @observacion
    );

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS validation_id;
END

/* ============================================================================
   SP 4. reclamo.sp_registrar_ajuste_manual

   Regla R10. El ajuste nace en estado PROPUESTO y no afecta ninguna cifra
   hasta que se apruebe. Exige motivo y antecedente: la restriccion no es
   opcional y esta ademas en el modelo.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_registrar_ajuste_manual]
(
    @FechaOperacion   date,
    @CampañaId        int,
    @PadId            int,
    @ModuloId         int,
    @TipoAjuste       varchar(30),
    @Motivo           nvarchar(500),
    @AntecedenteTipo  varchar(40),
    @AntecedenteRef   nvarchar(500),
    @DeltaM3          decimal(30,12) = NULL,
    @DeltaTms         decimal(30,12) = NULL,
    @ModuloDestinoId  int            = NULL,
    @Observacion      nvarchar(1000) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Motivo IS NULL OR LTRIM(RTRIM(@Motivo)) = ''
        THROW 60301, 'Todo ajuste manual exige un motivo.', 1;

    IF @AntecedenteRef IS NULL OR LTRIM(RTRIM(@AntecedenteRef)) = ''
        THROW 60302,
              'Todo ajuste manual exige la referencia del antecedente que lo respalda.', 1;

    IF @DeltaM3 IS NULL AND @DeltaTms IS NULL
        THROW 60303, 'Debe informar al menos delta en m3 o en TMS.', 1;

    IF @TipoAjuste = 'TRASPASO_MODULO' AND @ModuloDestinoId IS NULL
        THROW 60304, 'Un traspaso exige el modulo destino.', 1;

    /* Si viene solo uno de los dos deltas, se deriva el otro con la densidad
       oficial del modulo. Deja constancia en la observacion. */
    DECLARE @Densidad decimal(30,12) =
    (
        SELECT TOP (1) mc.densidad_oficial
        FROM [reclamo].[modulo_congelado] mc
        WHERE mc.[campaña_id] = @CampañaId AND mc.modulo_id = @ModuloId
    );

    DECLARE @Derivado nvarchar(200) = NULL;

    IF @DeltaM3 IS NULL AND @DeltaTms IS NOT NULL AND COALESCE(@Densidad,0) > 0
    BEGIN
        SET @DeltaM3 = @DeltaTms / @Densidad;
        SET @Derivado = N'delta_m3 derivado de delta_tms con densidad oficial '
                      + CAST(@Densidad AS nvarchar(40));
    END;

    IF @DeltaTms IS NULL AND @DeltaM3 IS NOT NULL AND COALESCE(@Densidad,0) > 0
    BEGIN
        SET @DeltaTms = @DeltaM3 * @Densidad;
        SET @Derivado = N'delta_tms derivado de delta_m3 con densidad oficial '
                      + CAST(@Densidad AS nvarchar(40));
    END;

    INSERT INTO [reclamo].[ajuste_manual]
    (
        fecha_operacion, [campaña_id], pad_id, modulo_id, modulo_destino_id,
        tipo_ajuste, delta_m3, delta_tms,
        motivo, antecedente_tipo, antecedente_ref,
        estado, observacion
    )
    VALUES
    (
        @FechaOperacion, @CampañaId, @PadId, @ModuloId, @ModuloDestinoId,
        @TipoAjuste, @DeltaM3, @DeltaTms,
        @Motivo, @AntecedenteTipo, @AntecedenteRef,
        'PROPUESTO',
        LTRIM(RTRIM(COALESCE(@Observacion, N'') + N' ' + COALESCE(@Derivado, N'')))
    );

    DECLARE @Id int = SCOPE_IDENTITY();

    PRINT 'Ajuste registrado en estado PROPUESTO. ajuste_id = ' + CAST(@Id AS varchar);
    PRINT 'No afecta ninguna cifra hasta que se apruebe con sp_aprobar_ajuste_manual.';

    SELECT * FROM [reclamo].[ajuste_manual] WHERE ajuste_id = @Id;
END;

/* ============================================================================
   SP 5. reclamo.sp_aprobar_ajuste_manual

   Separa quien propone de quien aprueba. El procedimiento impide que ambos
   sean el mismo login, salvo que se pase @PermitirAutoaprobacion = 1, lo que
   queda anotado en la observacion.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_aprobar_ajuste_manual]
(
    @AjusteId                int,
    @Decision                varchar(20),
    @Comentario              nvarchar(500) = NULL,
    @PermitirAutoaprobacion  bit = 0
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Decision NOT IN ('APROBADO','RECHAZADO','REVERTIDO')
        THROW 60401, 'La decision debe ser APROBADO, RECHAZADO o REVERTIDO.', 1;

    DECLARE @Solicitante sysname =
    (
        SELECT usuario_solicita FROM [reclamo].[ajuste_manual] WHERE ajuste_id = @AjusteId
    );

    IF @Solicitante IS NULL
        THROW 60402, 'No existe ese ajuste.', 1;

    IF @Solicitante = SUSER_SNAME() AND @PermitirAutoaprobacion = 0
        THROW 60403,
              'Quien propone un ajuste no deberia aprobarlo. Use @PermitirAutoaprobacion = 1 si corresponde.', 1;

    UPDATE [reclamo].[ajuste_manual]
    SET estado           = @Decision,
        usuario_aprueba  = SUSER_SNAME(),
        fecha_aprobacion = SYSDATETIME(),
        observacion      = LTRIM(RTRIM(COALESCE(observacion, N'')
                           + N' | ' + @Decision + N': ' + COALESCE(@Comentario, N'sin comentario')
                           + CASE WHEN @PermitirAutoaprobacion = 1
                                  THEN N' | AUTOAPROBADO POR EL SOLICITANTE' ELSE N'' END))
    WHERE ajuste_id = @AjusteId;

    PRINT 'Ajuste ' + CAST(@AjusteId AS varchar) + ' -> ' + @Decision;
    PRINT 'Recuerde reprocesar el rango con sp_calcular_reclamo_diario.';

    SELECT * FROM [reclamo].[ajuste_manual] WHERE ajuste_id = @AjusteId;
END;

CREATE PROCEDURE dbo.sp_corregir_totalizadores
    @schema_name NVARCHAR(128) = 'DB',           -- esquema de datos_filtrados
    @dry_run     BIT           = 0               -- 1 = solo reporta, no actualiza
AS
BEGIN
    SET NOCOUNT ON;

    -- -------------------------------------------------------------------------
    -- 0. Tabla de trabajo temporal (se reutiliza por columna limpiándola)
    -- -------------------------------------------------------------------------
    IF OBJECT_ID('tempdb..#Work')   IS NOT NULL DROP TABLE #Work;
    IF OBJECT_ID('tempdb..#Cols')   IS NOT NULL DROP TABLE #Cols;
    IF OBJECT_ID('tempdb..#Report') IS NOT NULL DROP TABLE #Report;

    CREATE TABLE #Work (
        rn       INT  NOT NULL,
        orig_val FLOAT    NULL,
        fix_val  FLOAT    NULL,
        PRIMARY KEY CLUSTERED (rn)
    );

    CREATE TABLE #Cols (
        col_id   INT IDENTITY(1,1) PRIMARY KEY,
        col_name NVARCHAR(128) NOT NULL
    );

    CREATE TABLE #Report (
        col_name        NVARCHAR(128),
        total_rows      INT,
        corrected_rows  INT
    );

    -- -------------------------------------------------------------------------
    -- 1. Detectar columnas *tot* en datos_filtrados
    -- -------------------------------------------------------------------------
    INSERT INTO #Cols (col_name)
    SELECT c.COLUMN_NAME
    FROM INFORMATION_SCHEMA.COLUMNS c
    WHERE c.TABLE_SCHEMA = @schema_name
      AND c.TABLE_NAME   = 'datos_filtrados'
      AND c.COLUMN_NAME  LIKE '%tot%'
    ORDER BY c.ORDINAL_POSITION;

    -- -------------------------------------------------------------------------
    -- 2. Cursor por columna
    -- -------------------------------------------------------------------------
    DECLARE @col_name   NVARCHAR(128);
    DECLARE @col_id     INT = 1;
    DECLARE @max_col_id INT = (SELECT MAX(col_id) FROM #Cols);
    DECLARE @sql        NVARCHAR(MAX);

    WHILE @col_id <= @max_col_id
    BEGIN
        SELECT @col_name = col_name FROM #Cols WHERE col_id = @col_id;

        -- Limpiar trabajo anterior
        TRUNCATE TABLE #Work;

        -- ---------------------------------------------------------------------
        -- 3. Cargar datos de la columna actual ordenados cronológicamente
        --    Convertimos decimales europeos (coma → punto) y casteamos a FLOAT
        -- ---------------------------------------------------------------------
        SET @sql = N'
        INSERT INTO #Work (rn, orig_val)
        SELECT
            ROW_NUMBER() OVER (ORDER BY [fecha_inicial]) AS rn,
            ISNULL(
                TRY_CAST(
                    REPLACE(CAST([' + @col_name + N'] AS VARCHAR(MAX)), '','', ''.'')
                AS FLOAT),
            0) AS orig_val
        FROM [' + @schema_name + N'].[datos_filtrados];';

        EXEC sp_executesql @sql;

        -- Inicializar fix_val = orig_val
        UPDATE #Work SET fix_val = orig_val;

        -- ---------------------------------------------------------------------
        -- 4. Loop plateau: si el valor cae respecto al anterior → mantener prev
        -- ---------------------------------------------------------------------
        DECLARE @rn     INT = 2;
        DECLARE @maxRn  INT = (SELECT MAX(rn) FROM #Work);
        DECLARE @cur    FLOAT;
        DECLARE @prev   FLOAT;

        WHILE @rn <= @maxRn
        BEGIN
            SELECT @cur  = fix_val FROM #Work WHERE rn = @rn;
            SELECT @prev = fix_val FROM #Work WHERE rn = @rn - 1;

            -- Caída detectada → plateau (mantener el último valor válido)
            IF @cur < @prev
                UPDATE #Work SET fix_val = @prev WHERE rn = @rn;

            SET @rn = @rn + 1;
        END;

        -- ---------------------------------------------------------------------
        -- 5. Reportar cuántas filas fueron corregidas
        -- ---------------------------------------------------------------------
        INSERT INTO #Report (col_name, total_rows, corrected_rows)
        SELECT
            @col_name,
            COUNT(*),
            SUM(CASE WHEN fix_val <> orig_val THEN 1 ELSE 0 END)
        FROM #Work;

        -- ---------------------------------------------------------------------
        -- 6. Aplicar corrección (UPDATE dinámico) si no es dry_run
        --    Usamos una CTE numerada para hacer el JOIN por posición
        -- ---------------------------------------------------------------------
        IF @dry_run = 0
        BEGIN
            -- Creamos tabla auxiliar numerada para hacer JOIN seguro
            IF OBJECT_ID('tempdb..#Numbered') IS NOT NULL DROP TABLE #Numbered;

            SET @sql = N'
            SELECT
                ROW_NUMBER() OVER (ORDER BY [fecha_inicial]) AS rn,
                [fecha_inicial]
            INTO #Numbered
            FROM [' + @schema_name + N'].[datos_filtrados];

            UPDATE d
            SET d.[' + @col_name + N'] = w.fix_val
            FROM [' + @schema_name + N'].[datos_filtrados] d
            JOIN #Numbered n ON n.[fecha_inicial] = d.[fecha_inicial]
            JOIN #Work w     ON w.rn = n.rn
            WHERE w.fix_val <> w.orig_val;

            DROP TABLE #Numbered;';

            EXEC sp_executesql @sql;
        END;

        SET @col_id = @col_id + 1;
    END;

    -- -------------------------------------------------------------------------
    -- 7. Resumen de ejecución
    -- -------------------------------------------------------------------------
    SELECT
        col_name        AS [Columna],
        total_rows      AS [Filas totales],
        corrected_rows  AS [Filas corregidas],
        CAST(ROUND(100.0 * corrected_rows / NULLIF(total_rows,0), 2) AS DECIMAL(5,2))
                        AS [% corregido]
    FROM #Report
    ORDER BY corrected_rows DESC;

    -- Limpieza
    DROP TABLE #Work;
    DROP TABLE #Cols;
    DROP TABLE #Report;
END;

/*
================================================================================
  05_sp_razon_lixiviacion_v2.sql
  Esquema : inventar_SpcHidr

  DEFINICIÓN DE RAZÓN DE LIXIVIACIÓN (RL):
    RL (m³/ton) = Σ caudal_acumulado (m³) / TMS_total (ton)

  COMPORTAMIENTO POR CAMPAÑA:
    - La misma parcela_numero aparece en múltiples campañas en las vistas
    - dia_ciclo y RL se REINICIAN en 1 al inicio de cada campaña
    - @campana_id filtra exactamente una campaña
    - La fecha de inicio del ciclo viene de campana_parcela_control.fecha_primer_riego

  PROBLEMA DE MÓDULOS MÚLTIPLES:
    campana_parcela_control tiene 2+ filas por (campana_id, parcela_id)
    porque cada módulo genera una fila. Se pre-agrega con GROUP BY para
    evitar que el JOIN duplique registros de flujo.

  MODELO DE DATOS:
    parcela                  → id_parcela, id_pad, numero
    campana_parcela_control  → campana_id, pad_id, parcela_id,
                               tms_cargado, cut_tm_total, cus_tm_total,
                               altura_modulo_max, fecha_primer_riego,
                               fecha_ultimo_riego, estado_ciclo
    v_flujos_oxido_unpivot   → fecha_registro, parcela_numero, caudal (m³/h)
    v_flujos_sulfuro_unpivot → fecha_registro, parcela_numero, caudal (m³/h)
    v_drena_oxido_unpivot    → fecha_registro, parcela_numero, cu_pp (g/L)
    v_drena_sulfuro_unpivot  → fecha_registro, parcela_numero, cu_pp (g/L)
    recuperaciones_pad       → Recuperacion_parcela acumulada (%)
    parcela_campana_cinetica → Rmax, k1, k2, A

  Parámetros:
    @parcela_id      INT
    @campana_id      INT
    @pad_id          INT   = NULL  (auto desde tabla parcela)
    @proyectar_dias  INT   = 0
    @factor_caudal   FLOAT = 24.0  (m³/h × 24 = m³/día)

  Uso:
      EXEC inventar_SpcHidr.sp_razon_lixiviacion @parcela_id=1, @campana_id=1;
      EXEC inventar_SpcHidr.sp_razon_lixiviacion @parcela_id=33, @campana_id=5;
      EXEC inventar_SpcHidr.sp_razon_lixiviacion @parcela_id=1, @campana_id=2,
           @proyectar_dias=30;
================================================================================
*/

CREATE   PROCEDURE inventar_SpcHidr.sp_razon_lixiviacion
    @parcela_id     INT,
    @campana_id     INT,
    @pad_id         INT   = NULL,
    @proyectar_dias INT   = 0,
    @factor_caudal  FLOAT = 24.0
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    /* -----------------------------------------------------------------------
       0. Resolver pad_id desde tabla parcela
    ----------------------------------------------------------------------- */
    IF @pad_id IS NULL
        SELECT TOP 1 @pad_id = id_pad
        FROM   inventar_SpcHidr.parcela
        WHERE  id_parcela = @parcela_id;

    /* -----------------------------------------------------------------------
       1. Parámetros base de la parcela para ESTA CAMPAÑA
          PRE-AGREGAR por campana_id para evitar duplicados de módulos.
          Cada parcela puede tener N módulos → SUM tms, MIN/MAX fechas.
    ----------------------------------------------------------------------- */
    DECLARE
        @tms_total      FLOAT       = 0,
        @cut_total      FLOAT       = 0,
        @cus_total      FLOAT       = 0,
        @altura_max     FLOAT       = 0,
        @parcela_numero INT         = 0,
        @numero_campana INT         = 0,
        @estado_ciclo   VARCHAR(20) = '',
        @fecha_ini      DATE        = NULL,
        @fecha_fin      DATE        = NULL,
        @dias_max_real  INT         = 0;

    SELECT
        @tms_total      = SUM(cpc.tms_cargado),
        @cut_total      = SUM(cpc.cut_tm_total),
        @cus_total      = SUM(cpc.cus_tm_total),
        @altura_max     = MAX(cpc.altura_modulo_max),
        @numero_campana = MAX(cpc.numero_campana),
        @estado_ciclo   = MAX(cpc.estado_ciclo),
        /* Inicio del ciclo = primer riego de la campaña en esta parcela */
        @fecha_ini      = CAST(MIN(cpc.fecha_primer_riego) AS DATE),
        /* Fin = último riego o hoy si sigue activa */
        @fecha_fin      = CAST(MAX(ISNULL(cpc.fecha_ultimo_riego,
                                          GETDATE())) AS DATE)
    FROM inventar_SpcHidr.campana_parcela_control cpc
    WHERE cpc.campana_id = @campana_id
      AND cpc.pad_id     = @pad_id
      AND cpc.parcela_id = @parcela_id;

    /* Número visible de parcela para vincular con las vistas */
    SELECT @parcela_numero = numero
    FROM   inventar_SpcHidr.parcela
    WHERE  id_parcela = @parcela_id;

    /* -----------------------------------------------------------------------
       2. Parámetros cinéticos para esta campaña
    ----------------------------------------------------------------------- */
    DECLARE
        @Rmax FLOAT = NULL,
        @k1   FLOAT = NULL,
        @k2   FLOAT = NULL,
        @A    FLOAT = NULL;

    SELECT TOP 1
        @Rmax = ck.Rmax,
        @k1   = ck.k1,
        @k2   = ck.k2,
        @A    = ck.A
    FROM inventar_SpcHidr.parcela_campana_cinetica ck
    WHERE ck.parcela_id = @parcela_id
      AND ck.campana_id = @campana_id
      AND ck.pad_id     = @pad_id;

    /* -----------------------------------------------------------------------
       3. Serie diaria de flujos para ESTA campaña
          dia_ciclo reinicia en 1 = primer día de riego de la campaña
          El filtro BETWEEN fecha_ini AND fecha_fin asegura que solo
          se incluyen los flujos del período de esta campaña
          (no los de campañas anteriores/posteriores con el mismo número de parcela)
    ----------------------------------------------------------------------- */
    CREATE TABLE #serie (
        fecha_registro  DATE,
        dia_ciclo       INT,
        caudal_m3_dia   FLOAT,
        cu_pp           FLOAT,
        rec_acum_pct    FLOAT
    );

    IF @pad_id = 1  /* PAD OXIDO: parcela_id 1..32 */
    BEGIN
        INSERT INTO #serie (fecha_registro, dia_ciclo, caudal_m3_dia, cu_pp)
        SELECT
            CAST(f.fecha_registro AS DATE)                  AS fecha_registro,
            /* dia_ciclo reinicia en 1 para esta campaña */
            DATEDIFF(day, @fecha_ini,
                     CAST(f.fecha_registro AS DATE)) + 1    AS dia_ciclo,
            ISNULL(f.caudal, 0) * @factor_caudal            AS caudal_m3_dia,
            d.cu_pp
        FROM inventar_SpcHidr.v_flujos_oxido_unpivot f
        LEFT JOIN inventar_SpcHidr.v_drena_oxido_unpivot d
               ON CAST(d.fecha_registro AS DATE) = CAST(f.fecha_registro AS DATE)
              AND d.parcela_numero               = f.parcela_numero
        WHERE f.parcela_numero = @parcela_numero
          /* Filtro de fechas de ESTA campaña — reinicia ciclo */
          AND CAST(f.fecha_registro AS DATE) >= @fecha_ini
          AND CAST(f.fecha_registro AS DATE) <= @fecha_fin;
    END
    ELSE  /* PAD SULFURO: parcela_id 33..60, numero 1..28 */
    BEGIN
        INSERT INTO #serie (fecha_registro, dia_ciclo, caudal_m3_dia, cu_pp)
        SELECT
            CAST(f.fecha_registro AS DATE),
            DATEDIFF(day, @fecha_ini,
                     CAST(f.fecha_registro AS DATE)) + 1,
            ISNULL(f.caudal, 0) * @factor_caudal,
            d.cu_pp
        FROM inventar_SpcHidr.v_flujos_sulfuro_unpivot f
        LEFT JOIN inventar_SpcHidr.v_drena_sulfuro_unpivot d
               ON CAST(d.fecha_registro AS DATE) = CAST(f.fecha_registro AS DATE)
              AND d.parcela_numero               = f.parcela_numero
        WHERE f.parcela_numero = @parcela_numero
          AND CAST(f.fecha_registro AS DATE) >= @fecha_ini
          AND CAST(f.fecha_registro AS DATE) <= @fecha_fin;
    END

    /* Recuperación acumulada para ESTA campaña desde recuperaciones_pad */
    UPDATE s
    SET    s.rec_acum_pct = rp.Recuperacion_parcela
    FROM   #serie s
    INNER JOIN inventar_SpcHidr.recuperaciones_pad rp
            ON CAST(rp.Fecha_drenaje AS DATE) = s.fecha_registro
           AND rp.parcela_id                  = @parcela_id
           AND CAST(rp.campaña_id AS INT)     = @campana_id;

    SELECT @dias_max_real = ISNULL(MAX(dia_ciclo), 0) FROM #serie;

    /* -----------------------------------------------------------------------
       4. Resultado histórico con RL y acumulados
          RL = Σ caudal_m3 / TMS_total  (reinicia por campaña)
    ----------------------------------------------------------------------- */
    SELECT
        s.dia_ciclo,
        s.fecha_registro,
        'real'                                              AS tipo,
        @campana_id                                         AS campana_id,
        @numero_campana                                     AS numero_campana,
        @pad_id                                             AS pad_id,
        @parcela_id                                         AS parcela_id,
        @parcela_numero                                     AS parcela_numero,

        /* Flujo diario (m³/día) */
        ROUND(s.caudal_m3_dia, 2)                          AS caudal_m3_dia,

        /* RL DIARIA = caudal_dia / TMS_total */
        ROUND(
            s.caudal_m3_dia / NULLIF(@tms_total, 0),
        6)                                                  AS rl_diaria,

        /* RL ACUMULADA = Σcaudal / TMS_total (reinicia en dia_ciclo=1) */
        ROUND(
            SUM(s.caudal_m3_dia)
                OVER (ORDER BY s.dia_ciclo
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            / NULLIF(@tms_total, 0),
        4)                                                  AS rl_acum,

        /* Volumen acumulado bruto (m³) */
        ROUND(
            SUM(s.caudal_m3_dia)
                OVER (ORDER BY s.dia_ciclo
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),
        2)                                                  AS volumen_acum_m3,

        /* Concentración Cu drenaje (g/L) */
        ROUND(s.cu_pp, 4)                                  AS cu_drenaje_gl,

        /* Cu extraído (ton/día) = caudal_m3 × cu_pp(g/L) / 1000 */
        ROUND(
            s.caudal_m3_dia * ISNULL(s.cu_pp, 0) / 1000.0,
        4)                                                  AS cu_diario_ton,

        /* Cu acumulado (ton) — reinicia por campaña */
        ROUND(
            SUM(s.caudal_m3_dia * ISNULL(s.cu_pp, 0) / 1000.0)
                OVER (ORDER BY s.dia_ciclo
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),
        4)                                                  AS cu_acum_ton,

        /* Recuperación real (%) de recuperaciones_pad */
        ROUND(s.rec_acum_pct, 2)                           AS rec_acum_pct,

        /* Recuperación modelo cinético (%) */
        CASE WHEN @Rmax IS NOT NULL THEN
            ROUND(
                @Rmax * (
                      @A       * (1 - EXP(-@k1 * s.dia_ciclo))
                    + (1 - @A) * (1 - EXP(-@k2 * s.dia_ciclo))
                ), 2)
        ELSE NULL END                                       AS rec_modelo_pct,

        /* Metadatos */
        @tms_total                                          AS tms_total,
        @cut_total                                          AS cut_tm_total,
        @cus_total                                          AS cus_tm_total,
        @altura_max                                         AS altura_modulo_max,
        @estado_ciclo                                       AS estado_ciclo,
        @Rmax                                               AS Rmax,
        @k1                                                 AS k1,
        @k2                                                 AS k2,
        @A                                                  AS A_fraccion_rapida

    FROM #serie s
    WHERE s.dia_ciclo >= 1

    UNION ALL

    /* -----------------------------------------------------------------------
       5. Proyección cinética (días futuros si @proyectar_dias > 0)
          RL proyectada usa caudal promedio histórico de ESTA campaña
    ----------------------------------------------------------------------- */
    SELECT
        @dias_max_real + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)),
        CAST(NULL AS DATE),
        'proyectado',
        @campana_id, @numero_campana, @pad_id,
        @parcela_id, @parcela_numero,
        hist.caudal_prom,
        ROUND(hist.caudal_prom / NULLIF(@tms_total, 0), 6),
        ROUND(
            (hist.vol_acum
             + hist.caudal_prom * ROW_NUMBER() OVER (ORDER BY (SELECT NULL)))
            / NULLIF(@tms_total, 0),
        4),
        ROUND(
            hist.vol_acum
            + hist.caudal_prom * ROW_NUMBER() OVER (ORDER BY (SELECT NULL)),
        2),
        CAST(NULL AS FLOAT),
        CAST(NULL AS FLOAT),
        CAST(NULL AS FLOAT),
        CAST(NULL AS FLOAT),
        CASE WHEN @Rmax IS NOT NULL THEN
            ROUND(
                @Rmax * (
                      @A       * (1 - EXP(-@k1 * (@dias_max_real + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)))))
                    + (1 - @A) * (1 - EXP(-@k2 * (@dias_max_real + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)))))
                ), 2)
        ELSE NULL END,
        @tms_total, @cut_total, @cus_total, @altura_max,
        @estado_ciclo, @Rmax, @k1, @k2, @A
    FROM (
        SELECT TOP (@proyectar_dias) 1 AS n FROM sys.all_columns
    ) p
    CROSS JOIN (
        SELECT
            AVG(caudal_m3_dia) AS caudal_prom,
            SUM(caudal_m3_dia) AS vol_acum
        FROM #serie
        WHERE dia_ciclo >= 1
    ) hist
    WHERE @proyectar_dias > 0
      AND @Rmax IS NOT NULL

    ORDER BY dia_ciclo;

    DROP TABLE #serie;

END;

CREATE   PROCEDURE
    inventar_SpcHidr.sp_guardar_contingencia_estado_operacional_test
(
    @FechaOperacional   date,
    @Turno              char(1),
    @EstadoOperacional  varchar(20),
    @Comentario         nvarchar(1000) = NULL,
    @Usuario            nvarchar(255)
)
AS
BEGIN

    SET NOCOUNT ON;
    SET XACT_ABORT ON;


    /* ============================================================
       NORMALIZACIÓN
       ============================================================ */

    DECLARE @TurnoNormalizado char(1);

    DECLARE @EstadoNormalizado varchar(20);

    DECLARE @UsuarioNormalizado nvarchar(255);

    DECLARE @ComentarioNormalizado nvarchar(1000);


    SET @TurnoNormalizado =
        UPPER(
            LTRIM(
                RTRIM(@Turno)
            )
        );


    SET @EstadoNormalizado =
        UPPER(
            LTRIM(
                RTRIM(@EstadoOperacional)
            )
        );


    SET @UsuarioNormalizado =
        LTRIM(
            RTRIM(@Usuario)
        );


    SET @ComentarioNormalizado =
        NULLIF(
            LTRIM(
                RTRIM(@Comentario)
            ),
            ''
        );


    /* ============================================================
       VALIDACIONES
       ============================================================ */

    IF @FechaOperacional IS NULL
        THROW 51101,
              'Debe informar @FechaOperacional.',
              1;


    IF @TurnoNormalizado NOT IN ('A', 'B')
        THROW 51102,
              '@Turno debe ser A o B.',
              1;


    IF @EstadoNormalizado NOT IN
    (
        'OPERATIVO',
        'MANTENCION',
        'CAIDA_PI'
    )
        THROW 51103,
              '@EstadoOperacional debe ser OPERATIVO, MANTENCION o CAIDA_PI.',
              1;


    IF @UsuarioNormalizado IS NULL
       OR LEN(@UsuarioNormalizado) = 0
        THROW 51104,
              'Debe informar @Usuario.',
              1;


    /* ============================================================
       INSERT APPEND-ONLY
       ============================================================ */

    INSERT INTO
        inventar_SpcHidr.contingencia_estado_operacional_test
    (
        fecha_operacional,
        turno,
        estado_operacional,
        comentario,
        usuario
    )

    OUTPUT
        inserted.id,
        inserted.fecha_operacional,
        inserted.turno,
        inserted.estado_operacional,
        inserted.comentario,
        inserted.usuario,
        inserted.fecha_registro

    VALUES
    (
        @FechaOperacional,
        @TurnoNormalizado,
        @EstadoNormalizado,
        @ComentarioNormalizado,
        @UsuarioNormalizado
    );

END;

-- Ejecuta esto en DBeaver para crear el procedimiento que falta
CREATE PROCEDURE inventar_SpcHidr.sp_Importar_Representatividad
(
    @Dia DATE,
    @TM1_TurnoA_Quimico NVARCHAR(50),
    @TM1_TurnoA_Fisico NVARCHAR(50),
    @TM1_TurnoB_Quimico NVARCHAR(50),
    @TM1_TurnoB_Fisico NVARCHAR(50),
    @TM2_TurnoA_Quimico NVARCHAR(50),
    @TM2_TurnoA_Fisico NVARCHAR(50),
    @TM2_TurnoB_Quimico NVARCHAR(50),
    @TM2_TurnoB_Fisico NVARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Esta instrucción revisa si la fecha ya existe:
    -- Si existe -> Actualiza los datos.
    -- Si no existe -> Inserta una fila nueva.
    MERGE inventar_SpcHidr.Representatividad_Diaria AS Target
    USING (SELECT @Dia AS Dia) AS Source
    ON (Target.Dia = Source.Dia)

    WHEN MATCHED THEN
        UPDATE SET
            TM1_TurnoA_Quimico = @TM1_TurnoA_Quimico,
            TM1_TurnoA_Fisico  = @TM1_TurnoA_Fisico,
            TM1_TurnoB_Quimico = @TM1_TurnoB_Quimico,
            TM1_TurnoB_Fisico  = @TM1_TurnoB_Fisico,
            TM2_TurnoA_Quimico = @TM2_TurnoA_Quimico,
            TM2_TurnoA_Fisico  = @TM2_TurnoA_Fisico,
            TM2_TurnoB_Quimico = @TM2_TurnoB_Quimico,
            TM2_TurnoB_Fisico  = @TM2_TurnoB_Fisico

    WHEN NOT MATCHED THEN
        INSERT (Dia, TM1_TurnoA_Quimico, TM1_TurnoA_Fisico, TM1_TurnoB_Quimico, TM1_TurnoB_Fisico, TM2_TurnoA_Quimico, TM2_TurnoA_Fisico, TM2_TurnoB_Quimico, TM2_TurnoB_Fisico)
        VALUES (@Dia, @TM1_TurnoA_Quimico, @TM1_TurnoA_Fisico, @TM1_TurnoB_Quimico, @TM1_TurnoB_Fisico, @TM2_TurnoA_Quimico, @TM2_TurnoA_Fisico, @TM2_TurnoB_Quimico, @TM2_TurnoB_Fisico);
END;

CREATE PROCEDURE inventar_SpcHidr.sp_corregir_totalizadores
    @dry_run BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    IF OBJECT_ID('tempdb..#Cols')   IS NOT NULL DROP TABLE #Cols;
    IF OBJECT_ID('tempdb..#Work')   IS NOT NULL DROP TABLE #Work;
    IF OBJECT_ID('tempdb..#Report') IS NOT NULL DROP TABLE #Report;

    -- -------------------------------------------------------------------------
    -- 1. Detectar columnas *tot*
    -- -------------------------------------------------------------------------
    CREATE TABLE #Cols (
        col_id   INT IDENTITY(1,1) PRIMARY KEY,
        col_name NVARCHAR(128) NOT NULL
    );

    INSERT INTO #Cols (col_name)
    SELECT COLUMN_NAME
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = 'inventar_SpcHidr'
      AND TABLE_NAME   = 'datos_filtrados'
      AND COLUMN_NAME  LIKE '%tot%'
    ORDER BY ORDINAL_POSITION;

    IF NOT EXISTS (SELECT 1 FROM #Cols)
    BEGIN
        SELECT 'No se encontraron columnas *tot* en inventar_SpcHidr.datos_filtrados' AS mensaje;
        RETURN;
    END;

    -- -------------------------------------------------------------------------
    -- 2. #Work: una fila por id_data, ordenada cronológicamente
    --    rn = posición cronológica, id_data = clave para el UPDATE final
    -- -------------------------------------------------------------------------
    CREATE TABLE #Work (
        rn       INT  NOT NULL PRIMARY KEY CLUSTERED,
        id_data  INT  NOT NULL,
        orig_val FLOAT    NULL,
        fix_val  FLOAT    NULL
    );

    CREATE TABLE #Report (
        col_name       NVARCHAR(128),
        total_rows     INT,
        corrected_rows INT
    );

    -- -------------------------------------------------------------------------
    -- 3. Loop por columna
    -- -------------------------------------------------------------------------
    DECLARE @col_name   NVARCHAR(128);
    DECLARE @col_id     INT = 1;
    DECLARE @max_col_id INT = (SELECT MAX(col_id) FROM #Cols);
    DECLARE @sql        NVARCHAR(MAX);
    DECLARE @rn         INT;
    DECLARE @maxRn      INT;
    DECLARE @cur        FLOAT;
    DECLARE @prev       FLOAT;
    DECLARE @corrected  INT;

    WHILE @col_id <= @max_col_id
    BEGIN
        SELECT @col_name = col_name FROM #Cols WHERE col_id = @col_id;

        -- Limpiar #Work para esta columna
        TRUNCATE TABLE #Work;

        -- INSERT directo con id_data como ancla — sin SQL dinámico para #Work
        -- Solo la referencia a la columna variable requiere SQL dinámico
        SET @sql = N'
        INSERT INTO #Work (rn, id_data, orig_val, fix_val)
        SELECT
            ROW_NUMBER() OVER (ORDER BY [fecha_inicial], [id_data]) AS rn,
            [id_data],
            ISNULL(TRY_CAST(REPLACE(CAST([' + @col_name + N'] AS VARCHAR(50)), '','', ''.'') AS FLOAT), 0),
            ISNULL(TRY_CAST(REPLACE(CAST([' + @col_name + N'] AS VARCHAR(50)), '','', ''.'') AS FLOAT), 0)
        FROM [inventar_SpcHidr].[datos_filtrados];';

        EXEC sp_executesql @sql;

        SELECT @maxRn = MAX(rn) FROM #Work;

        -- ---------------------------------------------------------------------
        -- 4. Plateau iterativo
        -- ---------------------------------------------------------------------
        SET @rn = 2;
        WHILE @rn <= @maxRn
        BEGIN
            SELECT @cur  = fix_val FROM #Work WHERE rn = @rn;
            SELECT @prev = fix_val FROM #Work WHERE rn = @rn - 1;

            IF @cur < @prev
                UPDATE #Work SET fix_val = @prev WHERE rn = @rn;

            SET @rn = @rn + 1;
        END;

        -- ---------------------------------------------------------------------
        -- 5. Registrar resultado
        -- ---------------------------------------------------------------------
        SELECT @corrected = SUM(CASE WHEN fix_val <> orig_val THEN 1 ELSE 0 END)
        FROM #Work;

        INSERT INTO #Report (col_name, total_rows, corrected_rows)
        VALUES (@col_name, @maxRn, ISNULL(@corrected, 0));

        -- ---------------------------------------------------------------------
        -- 6. Aplicar corrección por id_data — JOIN limpio, sin ambigüedad
        -- ---------------------------------------------------------------------
        IF @dry_run = 0 AND ISNULL(@corrected, 0) > 0
        BEGIN
            SET @sql = N'
            UPDATE d
            SET d.[' + @col_name + N'] = w.fix_val
            FROM [inventar_SpcHidr].[datos_filtrados] d
            JOIN #Work w ON w.id_data = d.[id_data]
            WHERE w.fix_val <> w.orig_val;';

            EXEC sp_executesql @sql;
        END;

        SET @col_id = @col_id + 1;
    END;

    -- -------------------------------------------------------------------------
    -- 7. Reporte final
    -- -------------------------------------------------------------------------
    SELECT
        col_name       AS [Columna],
        total_rows     AS [Filas totales],
        corrected_rows AS [Filas corregidas],
        CAST(ROUND(100.0 * corrected_rows / NULLIF(total_rows, 0), 2) AS DECIMAL(5,2))
                       AS [% corregido]
    FROM #Report
    ORDER BY corrected_rows DESC;

    DROP TABLE #Work;
    DROP TABLE #Cols;
    DROP TABLE #Report;
END;

/* Funcion de acceso, para que las vistas puedan leer la fecha de corte sin
   repetir el literal. */
CREATE   FUNCTION [reclamo].[fn_fecha_corte]()
RETURNS date
AS
BEGIN
    RETURN
    (
        SELECT TRY_CONVERT(date, c.valor)
        FROM [reclamo].[configuracion] c
        WHERE c.clave = 'FECHA_CORTE_SISTEMA'
    );
END;

CREATE   PROCEDURE
    inventar_SpcHidr.sp_registrar_contingencia_pi_test
(
    @FechaOperacional date,
    @Turno            char(1),
    @Accion           varchar(30),
    @Motivo           varchar(30) = NULL,
    @Comentario       nvarchar(1000) = NULL,
    @Usuario          nvarchar(255)
)
AS
BEGIN

    SET NOCOUNT ON;
    SET XACT_ABORT ON;


    DECLARE @TurnoN char(1) =
        UPPER(LTRIM(RTRIM(@Turno)));

    DECLARE @AccionN varchar(30) =
        UPPER(LTRIM(RTRIM(@Accion)));

    DECLARE @MotivoN varchar(30) =
        NULLIF(
            UPPER(LTRIM(RTRIM(@Motivo))),
            ''
        );

    DECLARE @ComentarioN nvarchar(1000) =
        NULLIF(
            LTRIM(RTRIM(@Comentario)),
            ''
        );

    DECLARE @UsuarioN nvarchar(255) =
        LTRIM(RTRIM(@Usuario));


    /* ============================================================
       VALIDACIONES BÁSICAS
       ============================================================ */

    IF @FechaOperacional IS NULL
        THROW 51201,
              'Debe informar @FechaOperacional.',
              1;


    IF @TurnoN NOT IN ('A','B')
        THROW 51202,
              '@Turno debe ser A o B.',
              1;


    IF @AccionN NOT IN
    (
        'ACTIVAR_CONTINGENCIA',
        'CERRAR_CONTINGENCIA'
    )
        THROW 51203,
              '@Accion debe ser ACTIVAR_CONTINGENCIA o CERRAR_CONTINGENCIA.',
              1;


    IF @UsuarioN IS NULL
       OR LEN(@UsuarioN) = 0
        THROW 51204,
              'Debe informar @Usuario.',
              1;


    IF @AccionN = 'ACTIVAR_CONTINGENCIA'
       AND @MotivoN NOT IN
       (
           'CAIDA_PI',
           'MANTENCION',
           'COMUNICACIONES',
           'SERVIDOR',
           'OTRO'
       )
        THROW 51205,
              'Debe informar un motivo válido para activar la contingencia.',
              1;


    IF @AccionN = 'CERRAR_CONTINGENCIA'
        SET @MotivoN = NULL;


    /* ============================================================
       ESTADO VIGENTE EN EL PUNTO OPERACIONAL SOLICITADO
       ============================================================ */

    DECLARE @UltimaAccion varchar(30);


    SELECT TOP (1)
        @UltimaAccion = a.accion

    FROM inventar_SpcHidr.contingencia_pi_accion_test AS a

    WHERE
        a.fecha_operacional < @FechaOperacional

        OR
        (
            a.fecha_operacional = @FechaOperacional
            AND
            CASE
                WHEN a.turno = 'A' THEN 1
                ELSE 2
            END
            <=
            CASE
                WHEN @TurnoN = 'A' THEN 1
                ELSE 2
            END
        )

    ORDER BY
        a.fecha_operacional DESC,

        CASE
            WHEN a.turno = 'A' THEN 1
            ELSE 2
        END DESC,

        a.fecha_registro DESC,
        a.id DESC;


    /* ============================================================
       CONTROL DE TRANSICIONES
       ============================================================ */

    IF @AccionN = 'ACTIVAR_CONTINGENCIA'
       AND @UltimaAccion = 'ACTIVAR_CONTINGENCIA'
        THROW 51206,
              'La contingencia PI ya se encuentra activa para ese periodo.',
              1;


    IF @AccionN = 'CERRAR_CONTINGENCIA'
       AND ISNULL(@UltimaAccion, 'NORMAL')
           <> 'ACTIVAR_CONTINGENCIA'
        THROW 51207,
              'No existe una contingencia PI activa para cerrar en ese periodo.',
              1;


    /* ============================================================
       INSERT APPEND-ONLY
       ============================================================ */

    INSERT INTO inventar_SpcHidr.contingencia_pi_accion_test
    (
        fecha_operacional,
        turno,
        accion,
        motivo,
        comentario,
        usuario
    )

    OUTPUT
        inserted.id,
        inserted.fecha_operacional,
        inserted.turno,
        inserted.accion,
        inserted.motivo,
        inserted.comentario,
        inserted.usuario,
        inserted.fecha_registro

    VALUES
    (
        @FechaOperacional,
        @TurnoN,
        @AccionN,
        @MotivoN,
        @ComentarioN,
        @UsuarioN
    );

END;

CREATE   PROCEDURE
    [inventar_SpcHidr].[sp_generador_reporte_diario_emision_test]
(
    @fecha_inicio date,
    @fecha_fin    date
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* ============================================================
       GENERADOR REPORTE DIARIO — LÍNEA DE EMISIÓN

       La fecha final es exclusiva.

       La lógica Turno → Día se encuentra centralizada en:
       inventar_SpcHidr.fn_generador_reporte_diario_emision_test

       Este procedimiento actúa únicamente como interfaz de consulta.

       No modifica:
       - sp_generador_reporte_diario
       - fn_generador_reporte_diario
       - reporte_turno_cache
       ============================================================ */

    IF @fecha_inicio IS NULL
       OR @fecha_fin IS NULL
    BEGIN
        THROW 50001,
              'Las fechas de inicio y fin son obligatorias.',
              1;
    END;

    IF @fecha_inicio >= @fecha_fin
    BEGIN
        THROW 50002,
              'La fecha de inicio debe ser menor que la fecha de fin.',
              1;
    END;

    SELECT *
    FROM
        [inventar_SpcHidr].[fn_generador_reporte_diario_emision_test]
        (
            @fecha_inicio,
            @fecha_fin
        )
    ORDER BY Fecha;
END;

/* ================================================================
   ALTER inventar_SpcHidr.sp_mantiene_datos_conciliados_emision_test
   v1.15 -> v1.16
   ----------------------------------------------------------------
   UNICO CAMBIO: PASO 3 (Ley CuT mina + stock).

   Motivo: Ley_CuT_Mina_Stock (insumo 4 de 7 para calcular
   Ley_CuT_Real_srr) leia solo mov_cam.CuTG00. Para 01-03 ago 2026
   ese laboratorio todavia no cargaba leyes para los camiones
   Destino=CH01, asi que #LeyMinaStock quedaba con CERO filas esos
   dias y Ley_CuT_Real_srr salia NULL aunque los otros 6 insumos
   estuvieran completos.

   Fix: mismo patron que PASO 2 (Chancado) y que
   v_conciliacion_chancado_v2 -- si mov_cam no tiene fila valida
   para una fecha, se usa como preliminar el promedio ponderado de
   "cut" en DEV_SIIR.hidro.imp_csv con el mismo filtro que ya usa
   Chancado (to='CH01', shovel<>'SRR', origen='IMP'). No reemplaza
   mov_cam cuando este si tiene datos -- solo llena el hueco.

   Se agrega la columna Fuente_Ley_Mina_Stock ('MOV_CAM' o
   'IMP_CSV_PRELIMINAR') a #LeyMinaStock para trazabilidad. No se
   toca el MERGE final ni la tabla Datos_conciliados_of: el JOIN
   contra #LeyMinaStock solo usa Fecha y Ley_CuT_Mina_Stock, asi
   que la columna nueva no requiere cambios aguas abajo.

   Nota: ic.tonnage en imp_csv es tonelaje humedo (no seco), igual
   que ya se acepta como aproximacion preliminar en PASO 2 para
   Chancado -- coherente con la Seccion 9 del prompt maestro
   (diferencia metodologica temporalmente aceptada).

   Todo lo demas (PASO 1, 2, 4-11, limpieza de temporales, manejo
   de errores) queda identico a la version que Luis ya valido.
================================================================ */
CREATE PROCEDURE [inventar_SpcHidr].[sp_mantiene_datos_conciliados_emision_test]
(
    @FechaInicio      date,
    @FechaFin         date,
    @DiasReproceso    int = 7,
    @RefrescarFactor  bit = 1
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
    IF @FechaInicio IS NULL OR @FechaFin IS NULL
        THROW 50001, 'Debe informar @FechaInicio y @FechaFin.', 1;
    IF @FechaInicio > @FechaFin
        THROW 50002, 'La fecha inicial no puede ser mayor que la fecha final.', 1;
    /* ================================================================
       CORTE DINAMICO DE CAMIONES
       Resuelve la ultima fecha realmente cargada dentro del mes de
       @FechaFin y no posterior al cierre solicitado.
    ================================================================ */
    DECLARE @InicioMesCorte date =
        DATEFROMPARTS(YEAR(@FechaFin), MONTH(@FechaFin), 1);
    DECLARE @FechaCorteCamiones date;
    /* Periodo cerrado: respetar la fotografia congelada. */
    SELECT TOP (1)
        @FechaCorteCamiones = cfg.[fecha_corte_camiones]
    FROM [inventar_SpcHidr].[configuracion_reclamo_rotopala_periodo] cfg
    WHERE cfg.[periodo_reporte] = @InicioMesCorte
      AND cfg.[pad_id] = 2
      AND cfg.[estado] = 'CERRADO'
      AND cfg.[fecha_corte_camiones] IS NOT NULL;
    /* Periodo abierto: utilizar la ultima carga realmente disponible. */
    IF @FechaCorteCamiones IS NULL
    BEGIN
        SELECT
            @FechaCorteCamiones = MAX(CAST(cr.[fecha] AS date))
        FROM [inventar_SpcHidr].
             [control_reclamo_sulfuro_camiones_thm_diario] cr
        WHERE CAST(cr.[fecha] AS date) >= @InicioMesCorte
          AND CAST(cr.[fecha] AS date) <= @FechaFin;
    END;
    IF @FechaCorteCamiones IS NULL
        THROW 52001,
              'No existe una fecha de corte de camiones valida para el periodo.',
              1;
    EXEC sys.sp_set_session_context
        @key   = N'fecha_corte_camiones',
        @value = @FechaCorteCamiones;
    PRINT '-- Corte dinamico camiones: '
        + CONVERT(varchar(10), @FechaCorteCamiones, 120);
    DECLARE @FechaInicioProceso date =
        CASE
            WHEN DATEADD(DAY, -@DiasReproceso, @FechaFin) < @FechaInicio
                THEN DATEADD(DAY, -@DiasReproceso, @FechaFin)
            ELSE @FechaInicio
        END;
    DECLARE @FechaFinExclusiva date = DATEADD(DAY, 1, @FechaFin);
    IF @RefrescarFactor = 1
    BEGIN
        EXEC [inventar_SpcHidr].[sp_mantiene_factor_ajuste_camiones_v2_test]
             @FechaInicio   = @FechaInicioProceso,
             @FechaFin      = @FechaFin,
             @DiasReproceso = @DiasReproceso;
    END
    ELSE
    BEGIN
        PRINT '-- Factor interno omitido: fotografía preparada por coordinador externo.';
    END;
    DECLARE @t0 datetime2        = SYSDATETIME();
    DECLARE @t1 datetime2;
    PRINT '-- INICIO: ' + CONVERT(varchar, @t0, 121);
    PRINT '-- Version: 1.16 (Ley CuT SRR: fallback IMP en Ley_CuT_Mina_Stock) -- destino: Datos_conciliados_of (PRODUCCION)';
    PRINT '-- Rango efectivo: ' + CONVERT(varchar, @FechaInicioProceso) + ' a ' + CONVERT(varchar, @FechaFin);
    /* ================================================================
       PASO 1: Calendario
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#Fechas') IS NOT NULL DROP TABLE #Fechas;
    ;WITH rec AS
    (
        SELECT @FechaInicioProceso AS Fecha
        UNION ALL
        SELECT DATEADD(DAY, 1, Fecha) FROM rec WHERE Fecha < @FechaFin
    )
    SELECT Fecha INTO #Fechas FROM rec OPTION (MAXRECURSION 1000);
    CREATE CLUSTERED INDEX ix_f ON #Fechas(Fecha);
    PRINT 'PASO 1  Calendario       : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@@ROWCOUNT AS varchar) + ' filas';
    /* ================================================================
       PASO 2: Chancado TMH                                   v1.11
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#Chancado')        IS NOT NULL DROP TABLE #Chancado;
    IF OBJECT_ID('tempdb..#ChancadoMovCam')  IS NOT NULL DROP TABLE #ChancadoMovCam;
    IF OBJECT_ID('tempdb..#ChancadoImpCsv')  IS NOT NULL DROP TABLE #ChancadoImpCsv;
    SELECT
        CAST(Fecha AS date)                AS Fecha,
        SUM(COALESCE(Tonelaje_Hum_CIO,0))  AS Chancado_TMH_Dia
    INTO #ChancadoMovCam
    FROM [inventar_SpcHidr].[mov_cam]
    WHERE Fase NOT LIKE '%SRR%'
      AND CAST(Fecha AS date) >= @FechaInicioProceso
      AND CAST(Fecha AS date) <= @FechaFin
    GROUP BY CAST(Fecha AS date);
    CREATE CLUSTERED INDEX ix_chmc ON #ChancadoMovCam(Fecha);
    SELECT
        CAST(ic.[date] AS date)             AS Fecha,
        SUM(COALESCE(ic.tonnage,0))         AS Chancado_TMH_Dia
    INTO #ChancadoImpCsv
    FROM [DEV_SIIR].[hidro].[imp_csv] ic
    WHERE ic.[to]     = 'CH01'
      AND ic.shovel  <> 'SRR'
      AND ic.origen   = 'IMP'
      AND CAST(ic.[date] AS date) >= @FechaInicioProceso
      AND CAST(ic.[date] AS date) <= @FechaFin
    GROUP BY CAST(ic.[date] AS date);
    CREATE CLUSTERED INDEX ix_chic ON #ChancadoImpCsv(Fecha);
    SELECT
        mc.Fecha,
        mc.Chancado_TMH_Dia,
        CAST('MOV_CAM' AS varchar(40))
            AS Fuente_Chancado_TMH,
        CAST('SUM_TONELAJE_HUM_CIO_FASE_NO_SRR' AS varchar(60))
            AS Metodo_Calculo_Chancado,
        CAST('OK' AS varchar(40))
            AS Flag_Chancado
    INTO #Chancado
    FROM #ChancadoMovCam mc
    UNION ALL
    SELECT
        ic.Fecha,
        ic.Chancado_TMH_Dia,
        CAST('IMP_CSV_PRELIMINAR' AS varchar(40)),
        CAST('SUM_TONNAGE_CH01_SIN_SRR_ORIGEN_IMP' AS varchar(60)),
        CAST('PRELIMINAR_PENDIENTE_MOV_CAM' AS varchar(40))
    FROM #ChancadoImpCsv ic
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM #ChancadoMovCam mc2
        WHERE mc2.Fecha = ic.Fecha
    );
    CREATE CLUSTERED INDEX ix_ch ON #Chancado(Fecha);
    DECLARE @ChFilas       int;
    DECLARE @ChMovCam      int;
    DECLARE @ChImpCsv      int;
    SELECT
        @ChFilas  = COUNT(*),
        @ChMovCam = SUM(CASE WHEN Fuente_Chancado_TMH = 'MOV_CAM' THEN 1 ELSE 0 END),
        @ChImpCsv = SUM(CASE WHEN Fuente_Chancado_TMH = 'IMP_CSV_PRELIMINAR' THEN 1 ELSE 0 END)
    FROM #Chancado;
    PRINT 'PASO 2  Chancado         : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(COALESCE(@ChFilas,0) AS varchar) + ' filas';
    /* ================================================================
       PASO 3: Ley CuT mina + stock                              v1.16
       Fallback IMP: ver comentario al inicio del script. Mismo
       patron que PASO 2 -- mov_cam manda si tiene datos, imp_csv
       rellena solo los dias que mov_cam dejo vacios.
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#LeyMinaStock')        IS NOT NULL DROP TABLE #LeyMinaStock;
    IF OBJECT_ID('tempdb..#LeyMinaStockMovCam')  IS NOT NULL DROP TABLE #LeyMinaStockMovCam;
    IF OBJECT_ID('tempdb..#LeyMinaStockImpCsv')  IS NOT NULL DROP TABLE #LeyMinaStockImpCsv;
    ;WITH MovCam_Deduplicado AS
    (
        SELECT
            m.*,
            rn = ROW_NUMBER() OVER
            (
                PARTITION BY
                    m.Fecha, m.Turno, m.Origen, m.Solido, m.Fase, m.Banco,
                    m.Pala, m.Destino, m.Poligono_CIO, m.Flota_CEX, m.Ton,
                    m.N_BREAK, m.[Ton hum diseño CAEX], m.Tonelaje_Hum_CIO,
                    m.Tonelaje_seco_CIO, m.PONDHumedad
                ORDER BY m.mov_id
            )
        FROM [inventar_SpcHidr].[mov_cam] AS m
        WHERE CAST(m.Fecha AS date) >= @FechaInicioProceso
          AND CAST(m.Fecha AS date) <= @FechaFin
          AND UPPER(LTRIM(RTRIM(ISNULL(m.Destino, '')))) = 'CH01'
          AND UPPER(LTRIM(RTRIM(ISNULL(m.Fase, '')))) <> 'SRR'
    )
    SELECT
        Fecha = CAST(Fecha AS date),
        Tonelaje_Mina_Stock = SUM(Tonelaje_seco_CIO),
        Ley_CuT_Mina_Stock = SUM(Tonelaje_seco_CIO * CuTG00) / NULLIF(SUM(Tonelaje_seco_CIO), 0),
        Cantidad_Registros_Validos = COUNT(*)
    INTO #LeyMinaStockMovCam
    FROM MovCam_Deduplicado
    WHERE rn = 1 AND Tonelaje_seco_CIO > 0 AND CuTG00 IS NOT NULL
    GROUP BY CAST(Fecha AS date);
    CREATE CLUSTERED INDEX ix_lms_mc ON #LeyMinaStockMovCam(Fecha);
    SELECT
        CAST(ic.[date] AS date) AS Fecha,
        SUM(COALESCE(ic.tonnage, 0)) AS Tonelaje_Mina_Stock,
        SUM(ic.tonnage * ic.cut)
            / NULLIF(SUM(CASE WHEN ic.cut IS NOT NULL THEN ic.tonnage ELSE NULL END), 0)
            AS Ley_CuT_Mina_Stock,
        COUNT(*) AS Cantidad_Registros_Validos
    INTO #LeyMinaStockImpCsv
    FROM [DEV_SIIR].[hidro].[imp_csv] ic
    WHERE ic.[to]     = 'CH01'
      AND ic.shovel  <> 'SRR'
      AND ic.origen   = 'IMP'
      AND ic.tonnage  > 0
      AND ic.cut IS NOT NULL
      AND CAST(ic.[date] AS date) >= @FechaInicioProceso
      AND CAST(ic.[date] AS date) <= @FechaFin
    GROUP BY CAST(ic.[date] AS date);
    CREATE CLUSTERED INDEX ix_lms_ic ON #LeyMinaStockImpCsv(Fecha);
    SELECT
        mc.Fecha,
        mc.Tonelaje_Mina_Stock,
        mc.Ley_CuT_Mina_Stock,
        mc.Cantidad_Registros_Validos,
        CAST('MOV_CAM' AS varchar(40)) AS Fuente_Ley_Mina_Stock
    INTO #LeyMinaStock
    FROM #LeyMinaStockMovCam mc
    UNION ALL
    SELECT
        ic.Fecha,
        ic.Tonelaje_Mina_Stock,
        ic.Ley_CuT_Mina_Stock,
        ic.Cantidad_Registros_Validos,
        CAST('IMP_CSV_PRELIMINAR' AS varchar(40))
    FROM #LeyMinaStockImpCsv ic
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM #LeyMinaStockMovCam mc2
        WHERE mc2.Fecha = ic.Fecha
    );
    CREATE CLUSTERED INDEX ix_lms ON #LeyMinaStock(Fecha);
    DECLARE @LmsFilas   int;
    DECLARE @LmsMovCam  int;
    DECLARE @LmsImpCsv  int;
    SELECT
        @LmsFilas  = COUNT(*),
        @LmsMovCam = SUM(CASE WHEN Fuente_Ley_Mina_Stock = 'MOV_CAM' THEN 1 ELSE 0 END),
        @LmsImpCsv = SUM(CASE WHEN Fuente_Ley_Mina_Stock = 'IMP_CSV_PRELIMINAR' THEN 1 ELSE 0 END)
    FROM #LeyMinaStock;
    PRINT 'PASO 3  Ley mina + stock: ' + CAST(DATEDIFF(ms, @t1, SYSDATETIME()) AS varchar) + ' ms - '
        + CAST(COALESCE(@LmsFilas,0) AS varchar) + ' filas ('
        + CAST(COALESCE(@LmsMovCam,0) AS varchar) + ' mov_cam, '
        + CAST(COALESCE(@LmsImpCsv,0) AS varchar) + ' imp_csv preliminar)';
    /* ================================================================
       PASO 4: Humedad / Sal / Apilado TMH
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#Apilado') IS NOT NULL DROP TABLE #Apilado;
    SELECT
        CAST(Fecha AS date)      AS Fecha,
        Humedad_Turno_A, Humedad_Turno_B, Humedad_promedio_dia,
        Sal_turno_A, Sal_Turno_B, Sal_promedio_dia,
        Apilado_TMH_turno_A, Apilado_TMH_turno_B, Apilado_TMH_promedio_dia
    INTO #Apilado
    FROM [inventar_SpcHidr].[Historico_Apilado_Diario]
    WHERE CAST(Fecha AS date) >= @FechaInicioProceso
      AND CAST(Fecha AS date) <= @FechaFin;
    CREATE CLUSTERED INDEX ix_ap ON #Apilado(Fecha);
    PRINT 'PASO 4  Apilado/Humedad  : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@@ROWCOUNT AS varchar) + ' filas';
    /* ================================================================
       PASO 5: Generador diario
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#Generador') IS NOT NULL DROP TABLE #Generador;
    SELECT
        g.Fecha, g.Apilado_TMS_Real_Dia, g.Apilado_TMS_Plan,
        g.Material_Operacion, g.Modulo, g.Avance, g.CuT_Real_Dia, g.CuT_Plan
    INTO #Generador
    FROM [inventar_SpcHidr].[fn_generador_reporte_diario_emision_test](@FechaInicioProceso, @FechaFinExclusiva) g;
    CREATE CLUSTERED INDEX ix_gen ON #Generador(Fecha);
    PRINT 'PASO 5  Generador diario : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@@ROWCOUNT AS varchar) + ' filas';
    /* ================================================================
       PASO 6: SRR diario
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#SRR') IS NOT NULL DROP TABLE #SRR;
    ;WITH srr_turno AS
    (
        SELECT
            CAST(Fecha AS date) AS Fecha,
            Turno,
            CASE
                WHEN SRR IS NULL OR Apilado_TMS_Real IS NULL THEN NULL
                ELSE Apilado_TMS_Real * SRR / 100.0
            END AS SRR_TMS_Turno
        FROM [inventar_SpcHidr].[reporte_turno_cache_emision_test]
        WHERE CAST(Fecha AS date) >= @FechaInicioProceso
          AND CAST(Fecha AS date) <= @FechaFin
    )
    SELECT
        Fecha,
        SUM(CASE WHEN Turno = 'A' THEN SRR_TMS_Turno END) AS SRR_TMS_Turno_A,
        SUM(CASE WHEN Turno = 'B' THEN SRR_TMS_Turno END) AS SRR_TMS_Turno_B,
        SUM(SRR_TMS_Turno)                                AS SRR_TMS_Dia,
        CASE
            WHEN COUNT(DISTINCT Turno) >= 2
             AND SUM(CASE WHEN SRR_TMS_Turno IS NULL THEN 1 ELSE 0 END) = 0
                THEN 'OK'
            WHEN SUM(SRR_TMS_Turno) IS NOT NULL
                THEN 'OK_PARCIAL'
            ELSE 'SIN_SRR_TMS'
        END AS Flag_SRR_TMS_Dia
    INTO #SRR
    FROM srr_turno
    GROUP BY Fecha;
    CREATE CLUSTERED INDEX ix_srr ON #SRR(Fecha);
    PRINT 'PASO 6  SRR              : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@@ROWCOUNT AS varchar) + ' filas';
    /* ================================================================
       PASO 7: Produccion catodica
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#Catodos') IS NOT NULL DROP TABLE #Catodos;
    SELECT
        CAST(Fecha AS date)     AS Fecha,
        Produccion_Catodos_Real
    INTO #Catodos
    FROM [inventar_SpcHidr].[v_produccion_catodica_diaria_test]
    WHERE CAST(Fecha AS date) >= @FechaInicioProceso
      AND CAST(Fecha AS date) <= @FechaFin;
    CREATE CLUSTERED INDEX ix_cat ON #Catodos(Fecha);
    PRINT 'PASO 7  Catodos          : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@@ROWCOUNT AS varchar) + ' filas';
    /* ================================================================
       PASO 8: Plan mensual
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#Plan') IS NOT NULL DROP TABLE #Plan;
    SELECT
        CAST(Fecha AS date)             AS Fecha,
        Ley_CuT_Plan_Fuente, Cobre_Fino_Apilado_Plan_Fuente,
        TMS_Rotopala_1_Plan, TMS_Rotopala_2_Plan,
        Camiones_TMS_Plan, Produccion_Catodos_Plan,
        SRR_TMS_Plan, Ley_CuT_Plan_SRR
    INTO #Plan
    FROM [inventar_SpcHidr].[v_planes_mensuales_diarios_test]
    WHERE CAST(Fecha AS date) >= @FechaInicioProceso
      AND CAST(Fecha AS date) <= @FechaFin;
    CREATE CLUSTERED INDEX ix_pm ON #Plan(Fecha);
    PRINT 'PASO 8  Plan mensual     : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@@ROWCOUNT AS varchar) + ' filas';
    /* ================================================================
       PASO 9: Reclamo base                                     v1.13
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#ReclamoBase') IS NOT NULL DROP TABLE #ReclamoBase;
    SELECT
        r.fecha_operacion              AS Fecha,
        r.pad_id, r.[campaña_id], r.modulo_id, r.modulo_numero, r.rotopala_id,
        r.avance_porcentaje, r.avance_total_porcentaje, r.avance_camiones_porcentaje,
        r.tonelaje_reclamado_diario, r.tonelaje_camiones_diario, r.volumen_diario_m3,
        r.fuente_reclamo, r.metodo_calculo, r.flag_calculo
    INTO #ReclamoBase
    FROM [reclamo].[v_reclamo_para_conciliados] r
    WHERE r.fecha_operacion >= @FechaInicioProceso
      AND r.fecha_operacion <= @FechaFin;
    CREATE CLUSTERED INDEX ix_rb ON #ReclamoBase(Fecha, pad_id);
    DECLARE @RbFilas int = @@ROWCOUNT;
    PRINT 'PASO 9  Reclamo base     : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - ' + CAST(@RbFilas AS varchar) + ' filas (fuente: reclamo.v_reclamo_para_conciliados)';
    /* ================================================================
       PASO 10: Reclamo TMS y contexto por pad                  v1.14
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#ReclamoOxidosTMS')   IS NOT NULL DROP TABLE #ReclamoOxidosTMS;
    IF OBJECT_ID('tempdb..#ReclamoSulfurosTMS')  IS NOT NULL DROP TABLE #ReclamoSulfurosTMS;
    IF OBJECT_ID('tempdb..#GanadorOxRaw')        IS NOT NULL DROP TABLE #GanadorOxRaw;
    IF OBJECT_ID('tempdb..#GanadorSuRaw')        IS NOT NULL DROP TABLE #GanadorSuRaw;
    IF OBJECT_ID('tempdb..#GanadorOx')           IS NOT NULL DROP TABLE #GanadorOx;
    IF OBJECT_ID('tempdb..#GanadorSu')           IS NOT NULL DROP TABLE #GanadorSu;
    IF OBJECT_ID('tempdb..#GrupoOx')             IS NOT NULL DROP TABLE #GrupoOx;
    IF OBJECT_ID('tempdb..#GrupoSu')             IS NOT NULL DROP TABLE #GrupoSu;
    IF OBJECT_ID('tempdb..#ReclamoOxidosCtx')    IS NOT NULL DROP TABLE #ReclamoOxidosCtx;
    IF OBJECT_ID('tempdb..#ReclamoSulfurosCtx')  IS NOT NULL DROP TABLE #ReclamoSulfurosCtx;
    SELECT Fecha, SUM(tonelaje_reclamado_diario) AS TMS_Rotopala_1_Real
    INTO #ReclamoOxidosTMS  FROM #ReclamoBase WHERE pad_id = 1 GROUP BY Fecha;
    SELECT Fecha, SUM(tonelaje_reclamado_diario) AS TMS_Rotopala_2_Real
    INTO #ReclamoSulfurosTMS FROM #ReclamoBase WHERE pad_id = 2 GROUP BY Fecha;
    SELECT
        rb.Fecha, rb.modulo_id, rb.modulo_numero, rb.avance_porcentaje,
        CAST(c.[numero_campaña] AS nvarchar(255)) AS campana_nombre,
        rb.[campaña_id], rb.tonelaje_reclamado_diario
    INTO #GanadorOxRaw
    FROM #ReclamoBase rb
    LEFT JOIN [inventar_SpcHidr].[campaña] c ON c.[id_campaña] = rb.[campaña_id]
    WHERE rb.pad_id = 1 AND rb.tonelaje_reclamado_diario > 0;
    CREATE CLUSTERED INDEX ix_gor ON #GanadorOxRaw(Fecha, modulo_numero);
    SELECT
        rb.Fecha, rb.modulo_id, rb.modulo_numero, rb.avance_porcentaje,
        CAST(c.[numero_campaña] AS nvarchar(255)) AS campana_nombre,
        rb.[campaña_id], rb.tonelaje_reclamado_diario
    INTO #GanadorSuRaw
    FROM #ReclamoBase rb
    LEFT JOIN [inventar_SpcHidr].[campaña] c ON c.[id_campaña] = rb.[campaña_id]
    WHERE rb.pad_id = 2 AND rb.tonelaje_reclamado_diario > 0;
    CREATE CLUSTERED INDEX ix_gsr ON #GanadorSuRaw(Fecha, modulo_numero);
    CREATE TABLE #GanadorOx (Fecha date NOT NULL PRIMARY KEY, modulo_numero int NULL, avance_porcentaje float NULL, campana_nombre nvarchar(255) NULL);
    CREATE TABLE #GanadorSu (Fecha date NOT NULL PRIMARY KEY, modulo_numero int NULL, avance_porcentaje float NULL, campana_nombre nvarchar(255) NULL);
    DECLARE @PisoOx int = 0, @CampanaPisoOx nvarchar(255) = NULL;
    DECLARE @PisoSu int = 0, @CampanaPisoSu nvarchar(255) = NULL;
    DECLARE @FechaCur date, @ModCur int, @AvanceCur float, @CampCur nvarchar(255);
    DECLARE dias_ox CURSOR LOCAL FAST_FORWARD FOR
        SELECT DISTINCT Fecha FROM #GanadorOxRaw ORDER BY Fecha;
    OPEN dias_ox;
    FETCH NEXT FROM dias_ox INTO @FechaCur;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @ModCur = NULL; SET @AvanceCur = NULL; SET @CampCur = NULL;
        SELECT TOP (1) @ModCur = modulo_numero, @AvanceCur = avance_porcentaje, @CampCur = campana_nombre
        FROM #GanadorOxRaw
        WHERE Fecha = @FechaCur
          AND (@CampanaPisoOx IS NULL OR campana_nombre <> @CampanaPisoOx OR modulo_numero >= @PisoOx)
        ORDER BY avance_porcentaje ASC, modulo_id DESC;
        IF @ModCur IS NOT NULL
        BEGIN
            INSERT INTO #GanadorOx (Fecha, modulo_numero, avance_porcentaje, campana_nombre)
            VALUES (@FechaCur, @ModCur, @AvanceCur, @CampCur);
            IF @CampanaPisoOx IS NULL OR @CampCur <> @CampanaPisoOx
            BEGIN
                SET @CampanaPisoOx = @CampCur;
                SET @PisoOx = @ModCur;
            END
            ELSE IF @ModCur > @PisoOx
                SET @PisoOx = @ModCur;
        END;
        FETCH NEXT FROM dias_ox INTO @FechaCur;
    END;
    CLOSE dias_ox;
    DEALLOCATE dias_ox;
    DECLARE dias_su CURSOR LOCAL FAST_FORWARD FOR
        SELECT DISTINCT Fecha FROM #GanadorSuRaw ORDER BY Fecha;
    OPEN dias_su;
    FETCH NEXT FROM dias_su INTO @FechaCur;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @ModCur = NULL; SET @AvanceCur = NULL; SET @CampCur = NULL;
        SELECT TOP (1) @ModCur = modulo_numero, @AvanceCur = avance_porcentaje, @CampCur = campana_nombre
        FROM #GanadorSuRaw
        WHERE Fecha = @FechaCur
          AND (@CampanaPisoSu IS NULL OR campana_nombre <> @CampanaPisoSu OR modulo_numero >= @PisoSu)
        ORDER BY avance_porcentaje ASC, modulo_id DESC;
        IF @ModCur IS NOT NULL
        BEGIN
            INSERT INTO #GanadorSu (Fecha, modulo_numero, avance_porcentaje, campana_nombre)
            VALUES (@FechaCur, @ModCur, @AvanceCur, @CampCur);
            IF @CampanaPisoSu IS NULL OR @CampCur <> @CampanaPisoSu
            BEGIN
                SET @CampanaPisoSu = @CampCur;
                SET @PisoSu = @ModCur;
            END
            ELSE IF @ModCur > @PisoSu
                SET @PisoSu = @ModCur;
        END;
        FETCH NEXT FROM dias_su INTO @FechaCur;
    END;
    CLOSE dias_su;
    DEALLOCATE dias_su;
    SELECT
        f.Fecha, g.modulo_numero, g.avance_porcentaje, g.campana_nombre,
        SUM(CASE WHEN g.Fecha IS NOT NULL THEN 1 ELSE 0 END) OVER (ORDER BY f.Fecha ROWS UNBOUNDED PRECEDING) AS grp
    INTO #GrupoOx
    FROM (SELECT DISTINCT Fecha FROM #ReclamoBase WHERE pad_id = 1) f
    LEFT JOIN #GanadorOx g ON g.Fecha = f.Fecha;
    SELECT
        Fecha,
        MAX(campana_nombre)    OVER (PARTITION BY grp) AS campana_nombre,
        MAX(modulo_numero)     OVER (PARTITION BY grp) AS modulo_numero,
        MAX(avance_porcentaje) OVER (PARTITION BY grp) AS avance_porcentaje
    INTO #ReclamoOxidosCtx
    FROM #GrupoOx;
    SELECT
        f.Fecha, g.modulo_numero, g.avance_porcentaje, g.campana_nombre,
        SUM(CASE WHEN g.Fecha IS NOT NULL THEN 1 ELSE 0 END) OVER (ORDER BY f.Fecha ROWS UNBOUNDED PRECEDING) AS grp
    INTO #GrupoSu
    FROM (SELECT DISTINCT Fecha FROM #ReclamoBase WHERE pad_id = 2) f
    LEFT JOIN #GanadorSu g ON g.Fecha = f.Fecha;
    SELECT
        Fecha,
        MAX(campana_nombre)    OVER (PARTITION BY grp) AS campana_nombre,
        MAX(modulo_numero)     OVER (PARTITION BY grp) AS modulo_numero,
        MAX(avance_porcentaje) OVER (PARTITION BY grp) AS avance_porcentaje
    INTO #ReclamoSulfurosCtx
    FROM #GrupoSu;
    DROP TABLE #GanadorOxRaw;
    DROP TABLE #GanadorSuRaw;
    DROP TABLE #GanadorOx;
    DROP TABLE #GanadorSu;
    DROP TABLE #GrupoOx;
    DROP TABLE #GrupoSu;
    CREATE CLUSTERED INDEX ix_ro  ON #ReclamoOxidosTMS(Fecha);
    CREATE CLUSTERED INDEX ix_rs  ON #ReclamoSulfurosTMS(Fecha);
    CREATE CLUSTERED INDEX ix_roc ON #ReclamoOxidosCtx(Fecha);
    CREATE CLUSTERED INDEX ix_rsc ON #ReclamoSulfurosCtx(Fecha);
    PRINT 'PASO 10 Reclamo ctx/TMS  : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms';
    /* ================================================================
       PASO 10b: Reclamo Camiones                                v1.13
    ================================================================ */
    SET @t1 = SYSDATETIME();
    IF OBJECT_ID('tempdb..#ReclamoCamionesTMS')  IS NOT NULL DROP TABLE #ReclamoCamionesTMS;
    IF OBJECT_ID('tempdb..#GanadorCamRaw')       IS NOT NULL DROP TABLE #GanadorCamRaw;
    IF OBJECT_ID('tempdb..#GanadorCam')          IS NOT NULL DROP TABLE #GanadorCam;
    IF OBJECT_ID('tempdb..#GrupoCam')            IS NOT NULL DROP TABLE #GrupoCam;
    IF OBJECT_ID('tempdb..#ReclamoCamionesCtx')  IS NOT NULL DROP TABLE #ReclamoCamionesCtx;
    SELECT
        rb.Fecha,
        SUM(CASE WHEN rb.pad_id = 1 THEN rb.tonelaje_camiones_diario ELSE 0 END) AS Camiones_TMS_Reclamo_Oxidos,
        SUM(CASE WHEN rb.pad_id = 2 THEN rb.tonelaje_camiones_diario ELSE 0 END) AS Camiones_TMS_Reclamo_Sulfuros,
        SUM(rb.tonelaje_camiones_diario) AS Camiones_TMS_total
    INTO #ReclamoCamionesTMS
    FROM #ReclamoBase rb
    GROUP BY rb.Fecha;
    CREATE CLUSTERED INDEX ix_rct ON #ReclamoCamionesTMS(Fecha);
    SELECT
        rb.Fecha,
        CAST(rb.modulo_numero AS nvarchar(255))   AS Modulo_reclamo_camiones,
        CAST(c.[numero_campaña] AS nvarchar(255)) AS Campana_reclamo_camiones,
        ROW_NUMBER() OVER (PARTITION BY rb.Fecha ORDER BY rb.tonelaje_camiones_diario DESC, rb.modulo_id DESC) AS rn
    INTO #GanadorCamRaw
    FROM #ReclamoBase rb
    LEFT JOIN [inventar_SpcHidr].[campaña] c ON c.[id_campaña] = rb.[campaña_id]
    WHERE rb.tonelaje_camiones_diario > 0;
    SELECT Fecha, Modulo_reclamo_camiones, Campana_reclamo_camiones
    INTO #GanadorCam
    FROM #GanadorCamRaw
    WHERE rn = 1;
    SELECT
        f.Fecha, g.Campana_reclamo_camiones, g.Modulo_reclamo_camiones,
        SUM(CASE WHEN g.Fecha IS NOT NULL THEN 1 ELSE 0 END) OVER (ORDER BY f.Fecha ROWS UNBOUNDED PRECEDING) AS grp
    INTO #GrupoCam
    FROM (SELECT DISTINCT Fecha FROM #ReclamoBase) f
    LEFT JOIN #GanadorCam g ON g.Fecha = f.Fecha;
    SELECT
        Fecha,
        MAX(Campana_reclamo_camiones) OVER (PARTITION BY grp) AS Campana_reclamo_camiones,
        MAX(Modulo_reclamo_camiones)  OVER (PARTITION BY grp) AS Modulo_reclamo_camiones
    INTO #ReclamoCamionesCtx
    FROM #GrupoCam;
    DROP TABLE #GanadorCamRaw;
    DROP TABLE #GanadorCam;
    DROP TABLE #GrupoCam;
    CREATE CLUSTERED INDEX ix_rcc ON #ReclamoCamionesCtx(Fecha);
    PRINT 'PASO 10b Reclamo camiones: ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms';
    /* ================================================================
       PASO 11: MERGE final
       Sin cambios respecto de la version validada -- el JOIN contra
       #LeyMinaStock solo usa Fecha y Ley_CuT_Mina_Stock, asi que la
       columna nueva Fuente_Ley_Mina_Stock (PASO 3) no requiere tocar
       nada aqui.
    ================================================================ */
    SET @t1 = SYSDATETIME();
    MERGE [inventar_SpcHidr].[Datos_conciliados_of] AS tgt
    USING
    (
        SELECT
            f.Fecha,
            aj.Chancado_TMS_Reporte AS Chancado_TMS_Real,
            a.Humedad_Turno_A, a.Humedad_Turno_B, a.Humedad_promedio_dia,
            a.Sal_turno_A, a.Sal_Turno_B, a.Sal_promedio_dia,
            CASE
                WHEN a.Apilado_TMH_turno_A IS NULL THEN NULL
                ELSE (a.Apilado_TMH_turno_A + COALESCE(a.Sal_turno_A, 0)) * COALESCE(aj.Factor_Aplicacion_Reportes, 1.0) - COALESCE(a.Sal_turno_A, 0)
            END AS Apilado_TMH_turno_A,
            CASE
                WHEN a.Apilado_TMH_turno_B IS NULL THEN NULL
                ELSE (a.Apilado_TMH_turno_B + COALESCE(a.Sal_turno_B, 0)) * COALESCE(aj.Factor_Aplicacion_Reportes, 1.0) - COALESCE(a.Sal_turno_B, 0)
            END AS Apilado_TMH_turno_B,
            aj.Apilado_TMH_Reporte AS Apilado_TMH_promedio_dia,
            aj.Apilado_TMS_Reporte AS Apilado_TMS_Real,
            g.Apilado_TMS_Plan     AS Apilado_TMS_Plan,
            CASE
                WHEN UPPER(LTRIM(RTRIM(g.Material_Operacion))) IN ('SULFURO','SULFUROS') THEN 'Sulfuro'
                WHEN UPPER(LTRIM(RTRIM(g.Material_Operacion))) IN ('OXIDO','OXIDOS','OXIDO','OXIDOS') THEN 'Oxido'
                ELSE g.Material_Operacion
            END AS Campana_apilado,
            g.Modulo AS Modulo_apilado,
            g.Avance AS Avance_apilado,
            g.CuT_Real_Dia AS Ley_CuT_Real,
            g.CuT_Plan     AS Ley_CuT_Plan,
            CASE
                WHEN COALESCE(aj.Apilado_TMS_Reporte, 0) = 0 THEN 0
                WHEN g.CuT_Real_Dia IS NULL THEN NULL
                ELSE aj.Apilado_TMS_Reporte * g.CuT_Real_Dia / 100.0
            END AS Cobre_fino_Apilado_Real,
            pm.Cobre_Fino_Apilado_Plan_Fuente AS Cobre_fino_Apilado_Plan,
            ro_tms.TMS_Rotopala_1_Real,
            pm.TMS_Rotopala_1_Plan,
            CAST(ro_ctx.campana_nombre    AS nvarchar(255)) AS Campana_reclamo_oxidos,
            CAST(ro_ctx.modulo_numero     AS int)           AS Modulo_reclamo_oxidos,
            CAST(ro_ctx.avance_porcentaje AS float)         AS Avance_reclamo_oxidos,
            rs_tms.TMS_Rotopala_2_Real,
            pm.TMS_Rotopala_2_Plan,
            CAST(rs_ctx.campana_nombre    AS nvarchar(255)) AS Campana_reclamo_sulfuros,
            CAST(rs_ctx.modulo_numero     AS int)           AS modulo_reclamo_sulfuros,
            CAST(rs_ctx.avance_porcentaje AS float)         AS Avance_reclamo_sulfuros,
            rc_tms.Camiones_TMS_Reclamo_Oxidos,
            rc_tms.Camiones_TMS_Reclamo_Sulfuros,
            CAST(NULL AS nvarchar(255)) AS Movido,
            CAST(NULL AS nvarchar(255)) AS Extraido,
            rc_tms.Camiones_TMS_total                              AS Camiones_TMS_total,
            pm.Camiones_TMS_Plan        AS Camiones_TMS_plan,
            rc_ctx.Campana_reclamo_camiones,
            rc_ctx.Modulo_reclamo_camiones,
            CASE
                WHEN rc_tms.Camiones_TMS_total           IS NULL
                  OR ro_tms.TMS_Rotopala_1_Real            IS NULL
                  OR rs_tms.TMS_Rotopala_2_Real            IS NULL
                    THEN NULL
                ELSE rc_tms.Camiones_TMS_total + ro_tms.TMS_Rotopala_1_Real + rs_tms.TMS_Rotopala_2_Real
            END AS Total_Ripios_Incluye_Camiones_Real,
            CASE
                WHEN pm.TMS_Rotopala_1_Plan IS NOT NULL
                 AND pm.TMS_Rotopala_2_Plan IS NOT NULL
                 AND pm.Camiones_TMS_Plan   IS NOT NULL
                THEN CAST(pm.TMS_Rotopala_1_Plan AS float) + CAST(pm.TMS_Rotopala_2_Plan AS float) + CAST(pm.Camiones_TMS_Plan AS float)
                ELSE NULL
            END AS Total_Ripios_Incluye_Camiones_Plan,
            p.Produccion_Catodos_Real,
            pm.Produccion_Catodos_Plan,
            CASE WHEN s.Flag_SRR_TMS_Dia = 'OK' THEN s.SRR_TMS_Turno_A ELSE NULL END AS SRR_TMS_Turno_A,
            CASE WHEN s.Flag_SRR_TMS_Dia = 'OK' THEN s.SRR_TMS_Turno_B ELSE NULL END AS SRR_TMS_Turno_B,
            CASE WHEN s.Flag_SRR_TMS_Dia = 'OK' THEN s.SRR_TMS_Dia ELSE NULL END AS SRR_TMS_promedio_dia,
            pm.SRR_TMS_Plan,
            CASE
                WHEN ISNULL(s.Flag_SRR_TMS_Dia, '') <> 'OK' OR s.SRR_TMS_Dia IS NULL OR s.SRR_TMS_Dia <= 0 THEN NULL
                WHEN g.CuT_Real_Dia IS NULL THEN NULL
                WHEN lms.Ley_CuT_Mina_Stock IS NULL THEN NULL
                WHEN CASE WHEN COALESCE(aj.Flag_Usa_Ajuste, 0) = 1 THEN aj.Apilado_TMS_Bruto_Ajustado ELSE aj.Apilado_TMS_Bruto_Sin_Ajuste END IS NULL THEN NULL
                WHEN aj.Sal_TMH_Dia IS NULL THEN NULL
                WHEN aj.Delta_Inventario_Chancado_TMS IS NULL THEN NULL
                WHEN aj.Chancado_TMS_Reporte IS NULL THEN NULL
                ELSE
                    (
                        g.CuT_Real_Dia
                        * (
                            CASE WHEN COALESCE(aj.Flag_Usa_Ajuste, 0) = 1 THEN aj.Apilado_TMS_Bruto_Ajustado ELSE aj.Apilado_TMS_Bruto_Sin_Ajuste END
                            - aj.Sal_TMH_Dia
                            + aj.Delta_Inventario_Chancado_TMS
                          )
                        - (lms.Ley_CuT_Mina_Stock * aj.Chancado_TMS_Reporte)
                    )
                    / NULLIF(s.SRR_TMS_Dia, 0)
            END AS Ley_CuT_Real_srr,
            pm.Ley_CuT_Plan_SRR AS Ley_CuT_Plan_srr,
            CASE
                WHEN COALESCE(aj.Apilado_TMS_Reporte, 0) > 0 AND g.CuT_Real_Dia IS NULL THEN 2
                WHEN p.Produccion_Catodos_Real IS NULL THEN 1
                ELSE 0
            END AS estado
        FROM #Fechas       f
        LEFT JOIN #Chancado          c      ON c.Fecha      = f.Fecha
        LEFT JOIN #Apilado           a      ON a.Fecha      = f.Fecha
        LEFT JOIN #Generador         g      ON g.Fecha      = f.Fecha
        LEFT JOIN #SRR               s      ON s.Fecha      = f.Fecha
        LEFT JOIN #Catodos           p      ON p.Fecha      = f.Fecha
        LEFT JOIN #Plan              pm     ON pm.Fecha     = f.Fecha
        LEFT JOIN #LeyMinaStock     lms     ON lms.Fecha     = f.Fecha
        LEFT JOIN #ReclamoOxidosTMS  ro_tms ON ro_tms.Fecha = f.Fecha
        LEFT JOIN #ReclamoOxidosCtx  ro_ctx ON ro_ctx.Fecha = f.Fecha
        LEFT JOIN #ReclamoSulfurosTMS rs_tms ON rs_tms.Fecha = f.Fecha
        LEFT JOIN #ReclamoSulfurosCtx rs_ctx ON rs_ctx.Fecha = f.Fecha
        LEFT JOIN #ReclamoCamionesTMS rc_tms ON rc_tms.Fecha = f.Fecha
        LEFT JOIN #ReclamoCamionesCtx rc_ctx ON rc_ctx.Fecha = f.Fecha
        LEFT JOIN [inventar_SpcHidr].[v_ajuste_camiones_emision_test] aj ON aj.Fecha = f.Fecha
    ) AS src ON tgt.Fecha = src.Fecha
    WHEN MATCHED THEN UPDATE SET
        Chancado_TMS_Real                  = src.Chancado_TMS_Real,
        Humedad_Turno_A                    = src.Humedad_Turno_A,
        Humedad_Turno_B                    = src.Humedad_Turno_B,
        Humedad_promedio_dia               = src.Humedad_promedio_dia,
        Sal_turno_A                        = src.Sal_turno_A,
        Sal_Turno_B                        = src.Sal_Turno_B,
        Sal_promedio_dia                   = src.Sal_promedio_dia,
        Apilado_TMH_turno_A                = src.Apilado_TMH_turno_A,
        Apilado_TMH_turno_B                = src.Apilado_TMH_turno_B,
        Apilado_TMH_promedio_dia           = src.Apilado_TMH_promedio_dia,
        Apilado_TMS_Real                   = src.Apilado_TMS_Real,
        Apilado_TMS_Plan                   = src.Apilado_TMS_Plan,
        Campana_apilado                    = src.Campana_apilado,
        Modulo_apilado                     = src.Modulo_apilado,
        Avance_apilado                     = src.Avance_apilado,
        Ley_CuT_Real                       = src.Ley_CuT_Real,
        Ley_CuT_Plan                       = src.Ley_CuT_Plan,
        Cobre_fino_Apilado_Real            = src.Cobre_fino_Apilado_Real,
        Cobre_fino_Apilado_Plan            = src.Cobre_fino_Apilado_Plan,
        TMS_Rotopala_1_Real                = src.TMS_Rotopala_1_Real,
        TMS_Rotopala_1_Plan                = src.TMS_Rotopala_1_Plan,
        Campana_reclamo_oxidos             = src.Campana_reclamo_oxidos,
        Modulo_reclamo_oxidos              = src.Modulo_reclamo_oxidos,
        Avance_reclamo_oxidos              = src.Avance_reclamo_oxidos,
        TMS_Rotopala_2_Real                = src.TMS_Rotopala_2_Real,
        TMS_Rotopala_2_Plan                = src.TMS_Rotopala_2_Plan,
        Campana_reclamo_sulfuros           = src.Campana_reclamo_sulfuros,
        modulo_reclamo_sulfuros            = src.modulo_reclamo_sulfuros,
        Avance_reclamo_sulfuros            = src.Avance_reclamo_sulfuros,
        Camiones_TMS_Reclamo_Oxidos        = src.Camiones_TMS_Reclamo_Oxidos,
        Camiones_TMS_Reclamo_Sulfuros      = src.Camiones_TMS_Reclamo_Sulfuros,
        Movido                             = src.Movido,
        Extraido                           = src.Extraido,
        Camiones_TMS_total                 = src.Camiones_TMS_total,
        Camiones_TMS_plan                  = src.Camiones_TMS_plan,
        Campana_reclamo_camiones           = src.Campana_reclamo_camiones,
        Modulo_reclamo_camiones            = src.Modulo_reclamo_camiones,
        Total_Ripios_Incluye_Camiones_Real = src.Total_Ripios_Incluye_Camiones_Real,
        Total_Ripios_Incluye_Camiones_Plan = src.Total_Ripios_Incluye_Camiones_Plan,
        Produccion_Catodos_Real            = src.Produccion_Catodos_Real,
        Produccion_Catodos_Plan            = src.Produccion_Catodos_Plan,
        SRR_TMS_Turno_A                    = src.SRR_TMS_Turno_A,
        SRR_TMS_Turno_B                    = src.SRR_TMS_Turno_B,
        SRR_TMS_promedio_dia               = src.SRR_TMS_promedio_dia,
        SRR_TMS_Plan                       = src.SRR_TMS_Plan,
        Ley_CuT_Real_srr                   = src.Ley_CuT_Real_srr,
        Ley_CuT_Plan_srr                   = src.Ley_CuT_Plan_srr,
        estado                             = src.estado
    WHEN NOT MATCHED BY TARGET THEN INSERT
    (
        Fecha, Chancado_TMS_Real,
        Humedad_Turno_A, Humedad_Turno_B, Humedad_promedio_dia,
        Sal_turno_A, Sal_Turno_B, Sal_promedio_dia,
        Apilado_TMH_turno_A, Apilado_TMH_turno_B, Apilado_TMH_promedio_dia,
        Apilado_TMS_Real, Apilado_TMS_Plan,
        Campana_apilado, Modulo_apilado, Avance_apilado,
        Ley_CuT_Real, Ley_CuT_Plan,
        Cobre_fino_Apilado_Real, Cobre_fino_Apilado_Plan,
        TMS_Rotopala_1_Real, TMS_Rotopala_1_Plan,
        Campana_reclamo_oxidos, Modulo_reclamo_oxidos, Avance_reclamo_oxidos,
        TMS_Rotopala_2_Real, TMS_Rotopala_2_Plan,
        Campana_reclamo_sulfuros, modulo_reclamo_sulfuros, Avance_reclamo_sulfuros,
        Camiones_TMS_Reclamo_Oxidos, Camiones_TMS_Reclamo_Sulfuros,
        Movido, Extraido, Camiones_TMS_total, Camiones_TMS_plan,
        Campana_reclamo_camiones, Modulo_reclamo_camiones,
        Total_Ripios_Incluye_Camiones_Real, Total_Ripios_Incluye_Camiones_Plan,
        Produccion_Catodos_Real, Produccion_Catodos_Plan,
        SRR_TMS_Turno_A, SRR_TMS_Turno_B, SRR_TMS_promedio_dia, SRR_TMS_Plan,
        Ley_CuT_Real_srr, Ley_CuT_Plan_srr, estado
    )
    VALUES
    (
        src.Fecha, src.Chancado_TMS_Real,
        src.Humedad_Turno_A, src.Humedad_Turno_B, src.Humedad_promedio_dia,
        src.Sal_turno_A, src.Sal_Turno_B, src.Sal_promedio_dia,
        src.Apilado_TMH_turno_A, src.Apilado_TMH_turno_B, src.Apilado_TMH_promedio_dia,
        src.Apilado_TMS_Real, src.Apilado_TMS_Plan,
        src.Campana_apilado, src.Modulo_apilado, src.Avance_apilado,
        src.Ley_CuT_Real, src.Ley_CuT_Plan,
        src.Cobre_fino_Apilado_Real, src.Cobre_fino_Apilado_Plan,
        src.TMS_Rotopala_1_Real, src.TMS_Rotopala_1_Plan,
        src.Campana_reclamo_oxidos, src.Modulo_reclamo_oxidos, src.Avance_reclamo_oxidos,
        src.TMS_Rotopala_2_Real, src.TMS_Rotopala_2_Plan,
        src.Campana_reclamo_sulfuros, src.modulo_reclamo_sulfuros, src.Avance_reclamo_sulfuros,
        src.Camiones_TMS_Reclamo_Oxidos, src.Camiones_TMS_Reclamo_Sulfuros,
        src.Movido, src.Extraido, src.Camiones_TMS_total, src.Camiones_TMS_plan,
        src.Campana_reclamo_camiones, src.Modulo_reclamo_camiones,
        src.Total_Ripios_Incluye_Camiones_Real, src.Total_Ripios_Incluye_Camiones_Plan,
        src.Produccion_Catodos_Real, src.Produccion_Catodos_Plan,
        src.SRR_TMS_Turno_A, src.SRR_TMS_Turno_B, src.SRR_TMS_promedio_dia, src.SRR_TMS_Plan,
        src.Ley_CuT_Real_srr, src.Ley_CuT_Plan_srr, src.estado
    );
    PRINT 'PASO 11 MERGE            : ' + CAST(DATEDIFF(ms,@t1,SYSDATETIME()) AS varchar) + ' ms - '
        + CAST(@@ROWCOUNT AS varchar) + ' filas afectadas';
    PRINT '-- TOTAL                 : ' + CAST(DATEDIFF(ms,@t0,SYSDATETIME()) AS varchar) + ' ms';
    DROP TABLE IF EXISTS #Fechas;
    DROP TABLE IF EXISTS #Chancado;
