CREATE   PROCEDURE
    [inventar_SpcHidr].[sp_generador_reporte_diario]
(
    @fecha_inicio date,
    @fecha_fin    date
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* ============================================================
       GENERADOR REPORTE DIARIO

       La fecha final es exclusiva.

       La lógica Turno → Día se encuentra centralizada en:
       inventar_SpcHidr.fn_generador_reporte_diario

       Este procedimiento actúa únicamente como interfaz de consulta.
       ============================================================ */

    IF @fecha_inicio IS NULL
       OR @fecha_fin IS NULL
    BEGIN
        THROW 50001,
              'Las fechas de inicio y fin son obligatorias.',
              1;
    END;

    IF @fecha_inicio >= @fecha_fin
    BEGIN
        THROW 50002,
              'La fecha de inicio debe ser menor que la fecha de fin.',
              1;
    END;

    SELECT *
    FROM [inventar_SpcHidr].[fn_generador_reporte_diario]
    (
        @fecha_inicio,
        @fecha_fin
    )
    ORDER BY Fecha;
END;

/* -----------------------------------------------------------
   SECCION 4: Purga de ticks crudos con retencion de 30 dias,
   protegida: solo purga si ya no quedan intervalos sin resumir
   antes del limite.
----------------------------------------------------------- */
CREATE   PROCEDURE inventar_SpcHidr.sp_purgar_tot_TM
(
    @FechaFin        date,
    @DiasRetencion   int = 30
)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @FechaLimitePurga datetime2(3) = CAST(DATEADD(DAY, -@DiasRetencion, @FechaFin) AS datetime2(3));

    IF EXISTS
    (
        SELECT 1
        FROM inventar_SpcHidr.v_bitacora_rangos_norm r
        WHERE r.ts_fin < @FechaLimitePurga
          AND r.Torre IN ('T1','T2','SRR')
          AND NOT EXISTS
          (
              SELECT 1
              FROM inventar_SpcHidr.Resumen_Intervalo_TotTM s
              WHERE s.torre_id    = r.torre_id
                AND s.fecha_turno = r.fecha_turno
                AND s.turno_op    = r.turno_op
          )
    )
    BEGIN
        PRINT '-- Purga omitida: hay intervalos anteriores al limite de retencion aun no resumidos.';
        RETURN;
    END;

    DELETE FROM inventar_SpcHidr.tot_TM
    WHERE fecha < @FechaLimitePurga;

    PRINT '-- tot_TM purgado: filas con fecha < ' + CONVERT(varchar, @FechaLimitePurga);
END;

CREATE FUNCTION inventar_SpcHidr.fn_primer_riego_parcela
(
    @parcela_id     INT,
    @campana_id     INT,
    @fecha_min      DATE,   -- fecha_ini_carguio para filtrar datos históricos
    @fecha_max      DATE    -- fecha_ini siguiente campaña o '9999-12-31'
)
RETURNS DATE
AS
BEGIN
    DECLARE @col_num    INT;
    DECLARE @tipo_pad   VARCHAR(10);
    DECLARE @resultado  DATE = NULL;

    SELECT @col_num  = col_numero,
           @tipo_pad = tipo_pad
    FROM inventar_SpcHidr.aux_parcela_columna
    WHERE parcela_id = @parcela_id;

    IF @col_num IS NULL RETURN NULL;

    -- Construir nombre de columna dinámicamente no es posible en función escalar,
    -- por eso usamos UNPIVOT pre-calculado en vistas. Ver vistas abajo.
    -- Esta función se apoya en las vistas v_flujos_oxido_unpivot / v_flujos_sulfuro_unpivot

    IF @tipo_pad = 'oxido'
    BEGIN
        SELECT @resultado = MIN(CAST(fecha_registro AS DATE))
        FROM inventar_SpcHidr.v_flujos_oxido_unpivot
        WHERE parcela_numero = @col_num
          AND caudal > 0
          AND CAST(fecha_registro AS DATE) >= @fecha_min
          AND CAST(fecha_registro AS DATE) <= ISNULL(@fecha_max, '9999-12-31');
    END
    ELSE
    BEGIN
        SELECT @resultado = MIN(CAST(fecha_registro AS DATE))
        FROM inventar_SpcHidr.v_flujos_sulfuro_unpivot
        WHERE parcela_numero = @col_num
          AND caudal > 0
          AND CAST(fecha_registro AS DATE) >= @fecha_min
          AND CAST(fecha_registro AS DATE) <= ISNULL(@fecha_max, '9999-12-31');
    END;

    RETURN @resultado;
END;

/* ---------------------------------------------------------------------
   5. PROCEDIMIENTO: CLONAR UNA VERSIÓN
   Para partir de una proyección existente y ajustar solo lo necesario.
   --------------------------------------------------------------------- */
CREATE   PROCEDURE inventar_SpcHidr.sp_clonar_proyeccion
    @id_version_origen INT,
    @nombre_nuevo      VARCHAR(120),
    @creado_por        VARCHAR(100) = NULL,
    @id_version_nueva  INT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM inventar_SpcHidr.proyeccion_version
                   WHERE id_version = @id_version_origen)
    BEGIN
        RAISERROR('La version origen %d no existe.', 16, 1, @id_version_origen);
        RETURN;
    END

    INSERT INTO inventar_SpcHidr.proyeccion_version
        (nombre, descripcion, pad_id, fecha_corte, fecha_horizonte,
         estado, creado_por, id_version_padre, notas)
    SELECT @nombre_nuevo, descripcion, pad_id, fecha_corte, fecha_horizonte,
           'borrador', @creado_por, id_version, notas
    FROM inventar_SpcHidr.proyeccion_version
    WHERE id_version = @id_version_origen;

    SET @id_version_nueva = SCOPE_IDENTITY();

    INSERT INTO inventar_SpcHidr.proyeccion_parametro
        (id_version, campaña_id, parcela_id, pad_id, modelo,
         p1, p2, p3, p4, params_extra, fecha_inicio, dias_horizonte,
         origen, ajuste_r2, ajuste_rmse, n_puntos_ajuste, activo)
    SELECT @id_version_nueva, campaña_id, parcela_id, pad_id, modelo,
           p1, p2, p3, p4, params_extra, fecha_inicio, dias_horizonte,
           'heredado', ajuste_r2, ajuste_rmse, n_puntos_ajuste, activo
    FROM inventar_SpcHidr.proyeccion_parametro
    WHERE id_version = @id_version_origen;

    SELECT @id_version_nueva AS id_version_nueva;
END

CREATE   TRIGGER inventar_SpcHidr.tr_factor_camiones_vigencia_solapamiento_test
ON inventar_SpcHidr.factor_camiones_parametro_vigencia_test
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    -- Salvaguarda también para DML privilegiado. Serializa solo esta tabla pequeña.
    DECLARE @n bigint;
    SELECT @n=COUNT_BIG(*) FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test WITH (TABLOCKX,HOLDLOCK);
    IF EXISTS (
        SELECT 1 FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test a
        JOIN inventar_SpcHidr.factor_camiones_parametro_vigencia_test b
          ON a.id<b.id AND a.flota=b.flota AND a.parametro=b.parametro
        WHERE a.activo=1 AND b.activo=1
          AND (b.vigencia_hasta IS NULL OR a.vigencia_desde<b.vigencia_hasta)
          AND (a.vigencia_hasta IS NULL OR b.vigencia_desde<a.vigencia_hasta)
    ) THROW 51001, 'Existen vigencias superpuestas de limites de carga para ajuste.', 1;
END;

CREATE   PROCEDURE inventar_SpcHidr.sp_registrar_limite_factor_camiones_vigencia_test
    @Flota varchar(20),
    @Valor decimal(18,6),
    @VigenciaDesde date,
    @Motivo nvarchar(1000),
    @Usuario nvarchar(128)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF DB_NAME()<>N'inventar_SpcHidr' THROW 51000, 'Solo DEV.', 1;
    IF @Flota IS NULL OR @Flota NOT IN ('KOM','CAT') THROW 51010, 'Flota debe ser KOM o CAT.', 1;
    IF @Valor IS NULL OR @Valor<=0 THROW 51011, 'El limite debe ser mayor que cero.', 1;
    IF @VigenciaDesde IS NULL THROW 51012, 'Vigente desde es obligatorio.', 1;
    IF NULLIF(LTRIM(RTRIM(@Motivo)),N'') IS NULL OR NULLIF(LTRIM(RTRIM(@Usuario)),N'') IS NULL
        THROW 51013, 'Usuario y motivo son obligatorios.', 1;
    DECLARE @Propia bit=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;
    IF @Propia=1 BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Lock int, @N bigint;
        EXEC @Lock=sys.sp_getapplock @Resource='SIIR_FACTOR_CAMIONES_PARAMETROS_DEV',
            @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=15000;
        IF @Lock<0 THROW 51014, 'No fue posible bloquear los parametros; reintente.', 1;
        SELECT @N=COUNT_BIG(*) FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test WITH (TABLOCKX,HOLDLOCK);
        DECLARE @Mensaje nvarchar(2048);
        IF EXISTS (SELECT 1 FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test
                   WHERE flota=@Flota AND parametro='LIMITE_CARGA_AJUSTE' AND vigencia_desde=@VigenciaDesde)
        BEGIN
            SET @Mensaje=CONCAT('Ya existe una vigencia ',@Flota,' iniciada el ',CONVERT(varchar(10),@VigenciaDesde,105),'.');
            THROW 51015, @Mensaje, 1;
        END;
        DECLARE @Id bigint, @Anterior decimal(18,6), @Hasta date, @Siguiente date;
        IF (SELECT COUNT(*) FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test
            WHERE flota=@Flota AND parametro='LIMITE_CARGA_AJUSTE' AND activo=1
              AND vigencia_desde<=@VigenciaDesde AND (vigencia_hasta IS NULL OR @VigenciaDesde<vigencia_hasta))<>1
            THROW 51016, 'La fecha debe estar cubierta por exactamente una vigencia existente.', 1;
        SELECT @Id=id,@Anterior=valor,@Hasta=vigencia_hasta
        FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test
        WHERE flota=@Flota AND parametro='LIMITE_CARGA_AJUSTE' AND activo=1
          AND vigencia_desde<=@VigenciaDesde AND (vigencia_hasta IS NULL OR @VigenciaDesde<vigencia_hasta);
        SELECT @Siguiente=MIN(vigencia_desde) FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test
        WHERE flota=@Flota AND parametro='LIMITE_CARGA_AJUSTE' AND activo=1 AND vigencia_desde>@VigenciaDesde;
        IF @Hasta<>@Siguiente OR (@Hasta IS NULL AND @Siguiente IS NOT NULL) OR (@Hasta IS NOT NULL AND @Siguiente IS NULL)
            THROW 51017, 'Historia temporal inconsistente; revisar vigencias.', 1;
        DECLARE @Registro datetime2(7)=SYSDATETIME(), @Retro bit, @Fin date;
        SET @Retro=CASE WHEN @VigenciaDesde<CONVERT(date,@Registro) THEN 1 ELSE 0 END;
        UPDATE inventar_SpcHidr.factor_camiones_parametro_vigencia_test SET vigencia_hasta=@VigenciaDesde WHERE id=@Id;
        INSERT inventar_SpcHidr.factor_camiones_parametro_vigencia_test
            (flota,parametro,valor,vigencia_desde,vigencia_hasta,motivo,usuario_registro,fecha_registro)
        VALUES (@Flota,'LIMITE_CARGA_AJUSTE',@Valor,@VigenciaDesde,@Siguiente,@Motivo,@Usuario,@Registro);
        -- Verifica continuidad del historial completo de esta flota.
        IF EXISTS (SELECT 1 FROM (
            SELECT vigencia_hasta, LEAD(vigencia_desde) OVER (ORDER BY vigencia_desde) siguiente
            FROM inventar_SpcHidr.factor_camiones_parametro_vigencia_test
            WHERE flota=@Flota AND parametro='LIMITE_CARGA_AJUSTE' AND activo=1
        ) h WHERE vigencia_hasta<>siguiente OR (vigencia_hasta IS NULL AND siguiente IS NOT NULL)
                   OR (vigencia_hasta IS NOT NULL AND siguiente IS NULL))
            THROW 51017, 'Historia temporal inconsistente; revisar vigencias.', 1;
        INSERT inventar_SpcHidr.factor_camiones_parametro_auditoria_test
            (flota,parametro,accion,valor_anterior,valor_nuevo,vigencia_desde,usuario,motivo,fecha_registro,es_retroactivo)
        VALUES (@Flota,'LIMITE_CARGA_AJUSTE','NUEVA_VIGENCIA',@Anterior,@Valor,@VigenciaDesde,@Usuario,@Motivo,@Registro,@Retro);
        SELECT @Fin=MAX(Fecha) FROM inventar_SpcHidr.Control_Factor_Ajuste_Camiones_v2_test;
        IF @Propia=1 COMMIT;
        SELECT @Retro AS Es_Retroactivo, @VigenciaDesde AS Fecha_Inicio_Afectada,
               @Fin AS Fecha_Fin_Afectada, @Anterior AS Valor_Anterior, @Valor AS Valor_Nuevo;
    END TRY
    BEGIN CATCH
        IF @Propia=1 AND XACT_STATE()<>0 ROLLBACK;
        THROW;
    END CATCH;
END;

/* ============================================================
   3 PASOS ORQUESTADOS VIA inventar_SpcHidr.procedimientos_reportabilidad
   ------------------------------------------------------------
   La tabla control NO tiene columnas para pasar parametros (solo
   nombre_procedimiento + orden), asi que el motor que la lea
   presumiblemente hace "EXEC esquema.nombre_procedimiento" sin
   argumentos. Por eso se crean 3 wrappers parameterless que
   autocalculan la fecha ("ayer" para el objetivo diario) y llaman
   a los SP reales que ya construimos.

   SECCION A: wrappers parameterless (diario)
   SECCION B: sp_refrescar_historico_apilado_test SIN los EXEC
              internos (ahora son pasos 1 y 2 separados; si se
              dejan adentro Y en la tabla control, se ejecutarian
              2 veces)
   SECCION C: INSERT de los 3 pasos en la tabla control
============================================================ */

/* -----------------------------------------------------------
   SECCION A: Wrappers parameterless para el objetivo "diario"
----------------------------------------------------------- */

CREATE   PROCEDURE inventar_SpcHidr.sp_resumen_totTM_diario
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @DiasReproceso        int  = 7;
    DECLARE @FechaFin             date = DATEADD(DAY, -1, CAST(SYSUTCDATETIME() AS date));  -- "ayer"
    DECLARE @FechaInicio          date = @FechaFin;
    DECLARE @FechaLimiteReproceso date = DATEADD(DAY, -@DiasReproceso, @FechaFin);
    DECLARE @FechaInicioBorrado   date =
        CASE WHEN @FechaLimiteReproceso < @FechaInicio THEN @FechaLimiteReproceso ELSE @FechaInicio END;

    EXEC inventar_SpcHidr.sp_calcular_resumen_intervalo_totTM
         @FechaInicio = @FechaInicioBorrado,
         @FechaFin    = @FechaFin;
END;

CREATE   PROCEDURE inventar_SpcHidr.sp_purgar_totTM_diario
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @FechaFin date = DATEADD(DAY, -1, CAST(SYSUTCDATETIME() AS date));

    EXEC inventar_SpcHidr.sp_purgar_tot_TM
         @FechaFin      = @FechaFin,
         @DiasRetencion = 30;
END;

CREATE   PROCEDURE inventar_SpcHidr.sp_refrescar_historico_apilado_diario
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @FechaFin    date = DATEADD(DAY, -1, CAST(SYSUTCDATETIME() AS date));
    DECLARE @FechaInicio date = @FechaFin;

    EXEC inventar_SpcHidr.sp_refrescar_historico_apilado_test
         @FechaInicio   = @FechaInicio,
         @FechaFin      = @FechaFin,
         @DiasReproceso = 7;
END;

CREATE PROCEDURE inventar_SpcHidr.sp_rep_get_periodo_caso
    @caso_id INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @caso_id_out INT = NULL;
    DECLARE @fecha_inicio DATE = NULL;
    DECLARE @fecha_fin DATE = NULL;

    -- 2026-09-09 (v3): recon_caso PRIMERO. Es la UNICA fuente del dropdown
    -- "Caso Balance" de la UI; casos_balance queda solo como respaldo para
    -- corridas viejas ya no seleccionables. Invertido tras detectar
    -- colision real de IDs (caso 29 existe en ambos sistemas con periodos
    -- distintos: marzo 2025 en casos_balance vs. agosto 2026 en recon_caso).
    SELECT
        @caso_id_out = rc.id,
        @fecha_inicio = CAST(rc.fecha_inicio AS DATE),
        @fecha_fin = CAST(rc.fecha_fin AS DATE)
    FROM [DEV_SIIR].[hidro].[recon_caso] rc
    WHERE rc.id = @caso_id;

    IF @fecha_inicio IS NULL
    BEGIN
        SELECT
            @caso_id_out = c.caso_id,
            @fecha_inicio = CAST(c.fecha_ini AS DATE),
            @fecha_fin = CAST(c.fecha AS DATE)
        FROM inventar_SpcHidr.casos_balance c
        WHERE c.caso_id = @caso_id;
    END

    -- Un solo result set final (0 o 1 fila), critico para
    -- "INSERT INTO @tabla(...) EXEC sp_rep_get_periodo_caso" usado dentro
    -- de sp_rep_publish_oficial_validado.
    SELECT
        @caso_id_out AS caso_id,
        @fecha_inicio AS fecha_inicio,
        @fecha_fin AS fecha_fin
    WHERE @fecha_inicio IS NOT NULL;
END

/* ================================================================
   v2 de reclamo.sp_actualizar_disponible_rotopala y
   reclamo.sp_insertar_disponible_rotopala, con dos cambios pedidos:

   1) DENSIDAD AUTOMATICA. Si no se informa @Densidad explicita, y
      cambia TMS o m3_totales, la densidad se recalcula sola como
      TMS/m3_totales. Si se informa @Densidad, esa manda (override
      manual). Si no cambia ni TMS ni m3_totales, la densidad
      existente se conserva tal cual.

   2) PROPAGACION A MODULO YA CONGELADO. Si el (campaña_id, modulo_id)
      editado ya tiene una fila CONGELADO en reclamo.modulo_congelado,
      el cambio de tms_conformado/m3_totales/densidad_oficial se
      aplica TAMBIEN ahi (ya no queda desincronizado de disponible_
      rotopalas), y cada campo que cambio queda registrado en
      reclamo.log_sincronizacion (tabla_destino='modulo_congelado',
      tabla_origen='disponible_rotopalas (dashboard)', con valor
      anterior y nuevo). Nada de esto pasa si el modulo no esta
      congelado -- ahi disponible_rotopalas sigue siendo la unica
      fuente y modulo_congelado ni se toca.

   Ambas procedimientos devuelven, en su SELECT final, la columna
   propagado_a_modulo_congelado (bit) para que el dashboard pueda
   avisar explicitamente cuando esto ocurrio.
================================================================ */

CREATE   PROCEDURE [reclamo].[sp_actualizar_disponible_rotopala]
(
    @IdDisponibleRotopalas int,
    @Tms             decimal(30,12) = NULL,
    @M3Totales       decimal(30,12) = NULL,
    @Densidad        decimal(30,12) = NULL,
    @M3Apilado       decimal(30,12) = NULL,
    @TmhApilado      decimal(30,12) = NULL,
    @RemanenteM3     decimal(30,12) = NULL,
    @RemanenteTms    decimal(30,12) = NULL,
    @SoloInformados  bit = 1,
    @Observacion     nvarchar(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1 FROM [inventar_SpcHidr].[disponible_rotopalas]
        WHERE id_disponible_rotopalas = @IdDisponibleRotopalas
    )
        THROW 61001, 'No existe ese id_disponible_rotopalas.', 1;

    IF @Densidad IS NOT NULL AND @Densidad <= 0
        THROW 61002, 'La densidad debe ser mayor a 0.', 1;

    IF @Tms IS NOT NULL AND @Tms < 0
        THROW 61003, 'El TMS no puede ser negativo.', 1;

    IF @M3Totales IS NOT NULL AND @M3Totales < 0
        THROW 61004, 'El m3_totales no puede ser negativo.', 1;

    DECLARE @PadId bigint, @ModuloId bigint, @CampañaId bigint;
    DECLARE @TmsPrevio decimal(30,12), @M3Previo decimal(30,12), @DensidadPrevia decimal(30,12);

    SELECT @PadId = pad_id, @ModuloId = modulo_id, @CampañaId = [campaña_id],
           @TmsPrevio = tms, @M3Previo = m3_totales, @DensidadPrevia = densidad
    FROM [inventar_SpcHidr].[disponible_rotopalas]
    WHERE id_disponible_rotopalas = @IdDisponibleRotopalas;

    DECLARE @TmsNuevo decimal(30,12) =
        CASE WHEN @SoloInformados = 1 THEN COALESCE(@Tms, @TmsPrevio) ELSE @Tms END;
    DECLARE @M3Nuevo decimal(30,12) =
        CASE WHEN @SoloInformados = 1 THEN COALESCE(@M3Totales, @M3Previo) ELSE @M3Totales END;

    /* Densidad automatica: manual explicita manda; si no, se recalcula
       solo cuando cambio TMS o m3_totales; si no cambio nada de eso, se
       conserva la que ya tenia (o NULL si @SoloInformados=0 y no se
       informo densidad). */
    DECLARE @DensidadNueva decimal(30,12);
    IF @Densidad IS NOT NULL
        SET @DensidadNueva = @Densidad;
    ELSE IF (@Tms IS NOT NULL OR @M3Totales IS NOT NULL) AND COALESCE(@M3Nuevo, 0) > 0
        SET @DensidadNueva = @TmsNuevo / @M3Nuevo;
    ELSE IF @SoloInformados = 1
        SET @DensidadNueva = @DensidadPrevia;
    ELSE
        SET @DensidadNueva = NULL;

    BEGIN TRANSACTION;

    UPDATE [inventar_SpcHidr].[disponible_rotopalas]
    SET tms           = @TmsNuevo,
        m3_totales    = @M3Nuevo,
        densidad      = @DensidadNueva,
        m3_apilado    = CASE WHEN @SoloInformados = 1 THEN COALESCE(@M3Apilado, m3_apilado) ELSE @M3Apilado END,
        tmh_apilado   = CASE WHEN @SoloInformados = 1 THEN COALESCE(@TmhApilado, tmh_apilado) ELSE @TmhApilado END,
        remanente_m3  = CASE WHEN @SoloInformados = 1 THEN COALESCE(@RemanenteM3, remanente_m3) ELSE @RemanenteM3 END,
        remanente_tms = CASE WHEN @SoloInformados = 1 THEN COALESCE(@RemanenteTms, remanente_tms) ELSE @RemanenteTms END
    WHERE id_disponible_rotopalas = @IdDisponibleRotopalas;

    /* Propagacion: solo si el modulo ya esta CONGELADO. */
    IF EXISTS
    (
        SELECT 1 FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO'
    )
    BEGIN
        DECLARE @TmsCongPrevio decimal(30,12), @M3CongPrevio decimal(30,12), @DensCongPrevia decimal(30,12);

        SELECT @TmsCongPrevio = tms_conformado, @M3CongPrevio = m3_totales, @DensCongPrevia = densidad_oficial
        FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        UPDATE [reclamo].[modulo_congelado]
        SET tms_conformado   = @TmsNuevo,
            m3_totales       = @M3Nuevo,
            densidad_oficial = @DensidadNueva
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        INSERT INTO [reclamo].[log_sincronizacion]
            (tabla_destino, tabla_origen, accion, fecha_dato,
             [campaña_id], modulo_id, campo, valor_anterior, valor_nuevo, observacion)
        SELECT
            'modulo_congelado', 'disponible_rotopalas (dashboard)', 'ACTUALIZADO',
            CAST(SYSDATETIME() AS date),
            @CampañaId, @ModuloId, cambios.campo, cambios.valor_anterior, cambios.valor_nuevo,
            COALESCE(@Observacion, N'Editado desde disponible_rotopalas; modulo ya estaba congelado.')
        FROM
        (
            VALUES
                ('tms_conformado',   @TmsCongPrevio,  @TmsNuevo),
                ('m3_totales',       @M3CongPrevio,   @M3Nuevo),
                ('densidad_oficial', @DensCongPrevia, @DensidadNueva)
        ) AS cambios(campo, valor_anterior, valor_nuevo)
        WHERE NOT
        (
            (cambios.valor_anterior IS NULL AND cambios.valor_nuevo IS NULL)
            OR (cambios.valor_anterior IS NOT NULL AND cambios.valor_nuevo IS NOT NULL
                AND cambios.valor_anterior = cambios.valor_nuevo)
        );
    END;

    COMMIT TRANSACTION;

    SELECT dr.*,
           CASE WHEN EXISTS
           (
               SELECT 1 FROM [reclamo].[modulo_congelado] mc
               WHERE mc.[campaña_id] = @CampañaId AND mc.modulo_id = @ModuloId AND mc.estado = 'CONGELADO'
           ) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END AS propagado_a_modulo_congelado
    FROM [inventar_SpcHidr].[disponible_rotopalas] dr
    WHERE dr.id_disponible_rotopalas = @IdDisponibleRotopalas;
END;

CREATE   PROCEDURE [reclamo].[sp_insertar_disponible_rotopala]
(
    @PadId           bigint,
    @ModuloId        bigint,
    @CampañaId       bigint,
    @Campaña         int            = NULL,
    @Tms             decimal(30,12) = NULL,
    @M3Totales       decimal(30,12) = NULL,
    @Densidad        decimal(30,12) = NULL,
    @M3Apilado       decimal(30,12) = NULL,
    @TmhApilado      decimal(30,12) = NULL,
    @RemanenteM3     decimal(30,12) = NULL,
    @RemanenteTms    decimal(30,12) = NULL,
    @Observacion     nvarchar(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ModuloNumero int =
        (SELECT numero FROM [inventar_SpcHidr].[modulo] WHERE id_modulo = @ModuloId);

    IF @ModuloNumero IS NULL
        THROW 61011, 'modulo_id no existe en inventar_SpcHidr.modulo.', 1;

    IF EXISTS
    (
        SELECT 1 FROM [inventar_SpcHidr].[disponible_rotopalas]
        WHERE pad_id = @PadId AND modulo_id = @ModuloId AND [campaña_id] = @CampañaId
    )
        THROW 61012,
              'Ya existe un registro para ese pad_id, modulo_id y campaña_id. Use sp_actualizar_disponible_rotopala.', 1;

    IF @Campaña IS NULL
        SELECT TOP (1) @Campaña = dr.[campaña]
        FROM [inventar_SpcHidr].[disponible_rotopalas] dr
        WHERE dr.[campaña_id] = @CampañaId;

    IF @Campaña IS NULL
        THROW 61013,
              'No se pudo determinar el numero de campaña visible (@Campaña). Informelo explicitamente.', 1;

    IF @Densidad IS NOT NULL AND @Densidad <= 0
        THROW 61014, 'La densidad debe ser mayor a 0.', 1;

    IF @Tms IS NOT NULL AND @Tms < 0
        THROW 61015, 'El TMS no puede ser negativo.', 1;

    IF @M3Totales IS NOT NULL AND @M3Totales < 0
        THROW 61016, 'El m3_totales no puede ser negativo.', 1;

    /* Densidad automatica, igual criterio que en la actualizacion. */
    IF @Densidad IS NULL AND @Tms IS NOT NULL AND COALESCE(@M3Totales, 0) > 0
        SET @Densidad = @Tms / @M3Totales;

    BEGIN TRANSACTION;

    INSERT INTO [inventar_SpcHidr].[disponible_rotopalas]
    (
        pad_id, modulo, modulo_id, [campaña], [campaña_id],
        tms, m3_totales, densidad, m3_apilado, tmh_apilado,
        remanente_m3, remanente_tms
    )
    VALUES
    (
        @PadId, @ModuloNumero, @ModuloId, @Campaña, @CampañaId,
        @Tms, @M3Totales, @Densidad, @M3Apilado, @TmhApilado,
        @RemanenteM3, @RemanenteTms
    );

    /* Caso borde: si por alguna razon ya existia una linea base congelada
       para este modulo/campaña (por ejemplo, se recreo una fila borrada),
       se propaga y se deja registro igual que en la actualizacion. */
    IF EXISTS
    (
        SELECT 1 FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO'
    )
    BEGIN
        DECLARE @TmsCongPrevio2 decimal(30,12), @M3CongPrevio2 decimal(30,12), @DensCongPrevia2 decimal(30,12);

        SELECT @TmsCongPrevio2 = tms_conformado, @M3CongPrevio2 = m3_totales, @DensCongPrevia2 = densidad_oficial
        FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        UPDATE [reclamo].[modulo_congelado]
        SET tms_conformado   = COALESCE(@Tms, tms_conformado),
            m3_totales       = COALESCE(@M3Totales, m3_totales),
            densidad_oficial = COALESCE(@Densidad, densidad_oficial)
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        INSERT INTO [reclamo].[log_sincronizacion]
            (tabla_destino, tabla_origen, accion, fecha_dato,
             [campaña_id], modulo_id, campo, valor_anterior, valor_nuevo, observacion)
        SELECT
            'modulo_congelado', 'disponible_rotopalas (dashboard)', 'ACTUALIZADO',
            CAST(SYSDATETIME() AS date),
            @CampañaId, @ModuloId, cambios.campo, cambios.valor_anterior, cambios.valor_nuevo,
            COALESCE(@Observacion, N'Insertado en disponible_rotopalas; el modulo ya estaba congelado.')
        FROM
        (
            VALUES
                ('tms_conformado',   @TmsCongPrevio2,  COALESCE(@Tms, @TmsCongPrevio2)),
                ('m3_totales',       @M3CongPrevio2,   COALESCE(@M3Totales, @M3CongPrevio2)),
                ('densidad_oficial', @DensCongPrevia2, COALESCE(@Densidad, @DensCongPrevia2))
        ) AS cambios(campo, valor_anterior, valor_nuevo)
        WHERE NOT
        (
            (cambios.valor_anterior IS NULL AND cambios.valor_nuevo IS NULL)
            OR (cambios.valor_anterior IS NOT NULL AND cambios.valor_nuevo IS NOT NULL
                AND cambios.valor_anterior = cambios.valor_nuevo)
        );
    END;

    COMMIT TRANSACTION;

    SELECT dr.*,
           CASE WHEN EXISTS
           (
               SELECT 1 FROM [reclamo].[modulo_congelado] mc
               WHERE mc.[campaña_id] = @CampañaId AND mc.modulo_id = @ModuloId AND mc.estado = 'CONGELADO'
           ) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END AS propagado_a_modulo_congelado
    FROM [inventar_SpcHidr].[disponible_rotopalas] dr
    WHERE dr.pad_id = @PadId AND dr.modulo_id = @ModuloId AND dr.[campaña_id] = @CampañaId;
END;

