CREATE PROCEDURE inventar_SpcHidr.sp_rep_merge_ajustado_dyn
    @run_id UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @schema SYSNAME = 'inventar_SpcHidr';
    DECLARE @tgt SYSNAME = 'rep_prod_ajustado';
    DECLARE @stg SYSNAME = 'rep_prod_ajustado_stg';

    -- columnas a excluir del UPDATE/INSERT dinámico (metadata/control)
    DECLARE @exclude TABLE (col SYSNAME);
    INSERT INTO @exclude(col) VALUES
        ('run_id'),
        ('ts_ajuste'),
        ('factor_chancado'),
        ('factor_sal'),
        ('factor_finos'),
        ('estado');  -- <- CLAVE: excluir estado del dinámico

    DECLARE @set NVARCHAR(MAX) = N'';
    DECLARE @ins_cols NVARCHAR(MAX) = N'';
    DECLARE @ins_vals NVARCHAR(MAX) = N'';

    ;WITH common_cols AS (
        SELECT c1.name AS col_name
        FROM sys.columns c1
        INNER JOIN sys.objects o1 ON o1.object_id = c1.object_id
        INNER JOIN sys.schemas s1 ON s1.schema_id = o1.schema_id
        WHERE s1.name = @schema AND o1.name = @tgt

        INTERSECT

        SELECT c2.name
        FROM sys.columns c2
        INNER JOIN sys.objects o2 ON o2.object_id = c2.object_id
        INNER JOIN sys.schemas s2 ON s2.schema_id = o2.schema_id
        WHERE s2.name = @schema AND o2.name = @stg
    )
    SELECT
        @set = @set + CASE WHEN @set = N'' THEN N'' ELSE N',' + CHAR(10) END
             + N'    tgt.' + QUOTENAME(col_name) + N' = src.' + QUOTENAME(col_name),
        @ins_cols = @ins_cols + CASE WHEN @ins_cols = N'' THEN N'' ELSE N',' END
             + QUOTENAME(col_name),
        @ins_vals = @ins_vals + CASE WHEN @ins_vals = N'' THEN N'' ELSE N',' END
             + N'src.' + QUOTENAME(col_name)
    FROM common_cols
    WHERE col_name NOT IN (SELECT col FROM @exclude)
      AND col_name <> 'Fecha';   -- Fecha es clave, no se actualiza en el UPDATE

    -- Forzar estado=1 (una sola vez)
    IF @set = N''
        SET @set = N'    tgt.[estado] = 1';
    ELSE
        SET @set = @set + N',' + CHAR(10) + N'    tgt.[estado] = 1';

    -- FIX 2026-09-09: Fecha SI debe ir en el INSERT (es NOT NULL y es la
    -- clave del MERGE) - antes se excluia tambien del INSERT por el mismo
    -- filtro "col_name <> 'Fecha'" de arriba, lo que rompia el INSERT para
    -- cualquier fecha nunca antes insertada (siempre, en un caso/periodo
    -- nuevo) con "Cannot insert the value NULL into column 'Fecha'".
    SET @ins_cols = N'[Fecha],' + @ins_cols;
    SET @ins_vals = N'src.[Fecha],' + @ins_vals;

    -- En INSERT, agregamos estado explícito (una sola vez)
    SET @ins_cols = @ins_cols + CASE WHEN @ins_cols = N'' THEN N'' ELSE N',' END + N'[estado]';
    SET @ins_vals = @ins_vals + CASE WHEN @ins_vals = N'' THEN N'' ELSE N',' END + N'1';

    DECLARE @sql NVARCHAR(MAX) = N'
MERGE ' + QUOTENAME(@schema) + N'.' + QUOTENAME(@tgt) + N' AS tgt
USING (
    SELECT *
    FROM ' + QUOTENAME(@schema) + N'.' + QUOTENAME(@stg) + N'
    WHERE run_id = @run_id
) AS src
ON tgt.[Fecha] = src.[Fecha]
WHEN MATCHED THEN
    UPDATE SET
' + @set + N'
WHEN NOT MATCHED THEN
    INSERT (' + @ins_cols + N')
    VALUES (' + @ins_vals + N');
';

    EXEC sp_executesql @sql, N'@run_id UNIQUEIDENTIFIER', @run_id=@run_id;
END

	CREATE PROCEDURE dbo.sp_helpdiagramdefinition
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END

CREATE PROCEDURE dbo.sp_creatediagram
(
	@diagramname 	sysname,
	@owner_id		int	= null, 	
	@version 		int,
	@definition 	varbinary(max)
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on

	declare @theId int
	declare @retval int
	declare @IsDbo	int
	declare @userName sysname
	if(@version is null or @diagramname is null)
	begin
		RAISERROR (N'E_INVALIDARG', 16, 1);
		return -1
	end

	execute as caller;
	select @theId = DATABASE_PRINCIPAL_ID(); 
	select @IsDbo = IS_MEMBER(N'db_owner');
	revert; 
	
	if @owner_id is null
	begin
		select @owner_id = @theId;
	end
	else
	begin
		if @theId <> @owner_id
		begin
			if @IsDbo = 0
			begin
				RAISERROR (N'E_INVALIDARG', 16, 1);
				return -1
			end
			select @theId = @owner_id
		end
	end
	-- next 2 line only for test, will be removed after define name unique
	if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end

	insert into dbo.sysdiagrams(name, principal_id , version, definition)
			VALUES(@diagramname, @theId, @version, @definition) ;
	
	select @retval = @@IDENTITY 
	return @retval
END

CREATE PROCEDURE dbo.sp_renamediagram
(
	@diagramname 		sysname,
	@owner_id		int	= null,
	@new_diagramname	sysname

)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int
	declare @DiagIdTarg		int
	declare @u_name			sysname
	if((@diagramname is null) or (@new_diagramname is null))
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT;

	select @u_name = USER_NAME(@owner_id)

	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
	--	return 0;

	if(@u_name is null)
		select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
	else
		select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname

	if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end		

	if(@u_name is null)
		update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
	else
		update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
	return 0
END

	CREATE PROCEDURE dbo.sp_alterdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END

    CREATE PROCEDURE
        [inventar_SpcHidr].[sp_registrar_override_factor_camiones_test]
    (
        @FechaDesde date,
        @FechaHasta date,
        @Modo       varchar(50),
        @Motivo     nvarchar(max),
        @Usuario    nvarchar(4000)
    )
    AS
    BEGIN
        SET NOCOUNT ON;
        SET XACT_ABORT ON;

        SET @Modo =
            UPPER(LTRIM(RTRIM(@Modo)));

        SET @Motivo =
            LTRIM(RTRIM(@Motivo));

        SET @Usuario =
            LTRIM(RTRIM(@Usuario));


        IF @FechaDesde IS NULL
           OR @FechaHasta IS NULL
            THROW 53100,
                  'FechaDesde y FechaHasta son obligatorias.',
                  1;

        IF @FechaHasta < @FechaDesde
            THROW 53101,
                  'FechaHasta no puede ser anterior a FechaDesde.',
                  1;

        IF @Modo NOT IN ('FORZADO_1', 'AUTOMATICO')
            THROW 53102,
                  'Modo invalido. Use FORZADO_1 o AUTOMATICO.',
                  1;

        IF @Motivo IS NULL
           OR LEN(@Motivo) = 0
            THROW 53103,
                  'Motivo es obligatorio.',
                  1;

        IF LEN(@Motivo) > 1000
            THROW 53104,
                  'Motivo excede 1000 caracteres.',
                  1;

        IF @Usuario IS NULL
           OR LEN(@Usuario) = 0
            THROW 53105,
                  'Usuario es obligatorio.',
                  1;

        IF LEN(@Usuario) > 128
            THROW 53106,
                  'Usuario excede 128 caracteres.',
                  1;


        INSERT INTO
            inventar_SpcHidr.factor_camiones_override_aplicacion_test
        (
            fecha_desde,
            fecha_hasta,
            modo,
            motivo,
            usuario
        )
        VALUES
        (
            @FechaDesde,
            @FechaHasta,
            @Modo,
            CONVERT(nvarchar(1000), @Motivo),
            CONVERT(nvarchar(128), @Usuario)
        );


        DECLARE @IdOverride bigint =
            CONVERT(bigint, SCOPE_IDENTITY());

        DECLARE
            @FechaMinMaterializada date,
            @FechaMaxMaterializada date,
            @CantidadMaterializada bigint;


        SELECT
            @FechaMinMaterializada = MIN(f.Fecha),
            @FechaMaxMaterializada = MAX(f.Fecha),
            @CantidadMaterializada = COUNT_BIG(*)
        FROM
            inventar_SpcHidr.Control_Factor_Ajuste_Camiones_v2_test f
        WHERE
            f.Fecha BETWEEN @FechaDesde AND @FechaHasta;


        SELECT
            @IdOverride
                AS Id_Override,

            @FechaDesde
                AS Fecha_Desde,

            @FechaHasta
                AS Fecha_Hasta,

            @Modo
                AS Modo,

            DATEDIFF(DAY, @FechaDesde, @FechaHasta) + 1
                AS Cantidad_Dias_Rango,

            CAST(
                CASE
                    WHEN @FechaDesde < CAST(SYSDATETIME() AS date)
                        THEN 1
                    ELSE 0
                END
                AS bit
            ) AS Es_Retroactivo,

            CAST(
                CASE
                    WHEN COALESCE(@CantidadMaterializada, 0) > 0
                        THEN 1
                    ELSE 0
                END
                AS bit
            ) AS Afecta_Fechas_Materializadas,

            COALESCE(@CantidadMaterializada, 0)
                AS Cantidad_Fechas_Materializadas,

            @FechaMinMaterializada
                AS Fecha_Inicio_Materializada_Afectada,

            @FechaMaxMaterializada
                AS Fecha_Fin_Materializada_Afectada,

            CONVERT(nvarchar(1000), @Motivo)
                AS Motivo,

            CONVERT(nvarchar(128), @Usuario)
                AS Usuario,

            o.fecha_registro
                AS Fecha_Registro,

            CAST(0 AS bit)
                AS Reproceso_Automatico_Ejecutado

        FROM
            inventar_SpcHidr.factor_camiones_override_aplicacion_test o
        WHERE
            o.id_override = @IdOverride;
    END;

CREATE PROCEDURE dbo.sp_dropdiagram
(
	@diagramname 	sysname,
	@owner_id	int	= null
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT; 
	
	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	delete from dbo.sysdiagrams where diagram_id = @DiagId;

	return 0;
END

CREATE   PROCEDURE inventar_SpcHidr.sp_DatosConciliados_SetActiveRun
    @caso_id INT,
    @run_id UNIQUEIDENTIFIER,
    @usuario NVARCHAR(120) = NULL,
    @comentario NVARCHAR(400) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (
        SELECT 1
        FROM inventar_SpcHidr.Datos_conciliados_of_ver
        WHERE caso_id = @caso_id AND run_id = @run_id
    )
    BEGIN
        RAISERROR('No existe run_id para ese caso_id en Datos_conciliados_of_ver.', 16, 1);
        RETURN;
    END

    BEGIN TRAN;

        -- 1) Actualiza puntero activo
        MERGE inventar_SpcHidr.Datos_conciliados_of_active_run AS t
        USING (SELECT @caso_id AS caso_id, @run_id AS run_id) AS s
        ON (t.caso_id = s.caso_id)
        WHEN MATCHED THEN
            UPDATE SET run_id = s.run_id, ts_set = SYSUTCDATETIME(), usuario = @usuario, comentario = @comentario
        WHEN NOT MATCHED THEN
            INSERT (caso_id, run_id, ts_set, usuario, comentario)
            VALUES (s.caso_id, s.run_id, SYSUTCDATETIME(), @usuario, @comentario);

        -- 2) Marca flags (opcional, pero recomendado)
        UPDATE inventar_SpcHidr.Datos_conciliados_of_ver
        SET es_activa = CASE WHEN run_id = @run_id THEN 1 ELSE 0 END
        WHERE caso_id = @caso_id;

    COMMIT TRAN;
END

CREATE   PROCEDURE inventar_SpcHidr.sp_DatosConciliados_ClearActiveRun
    @caso_id INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRAN;

        DELETE FROM inventar_SpcHidr.Datos_conciliados_of_active_run
        WHERE caso_id = @caso_id;

        UPDATE inventar_SpcHidr.Datos_conciliados_of_ver
        SET es_activa = 0
        WHERE caso_id = @caso_id;

    COMMIT TRAN;
END

-- ============================================================
-- CONDUCTOR 1: todo lo previo al motor de reglas (Python)
-- ============================================================
CREATE   PROCEDURE inventar_SpcHidr.sp_rep_conductor_pre_ajuste
    @caso_id INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @run_id UNIQUEIDENTIFIER = NEWID();
    DECLARE @fecha_ini DATE, @fecha_fin DATE;

    -- (opcional) mantiene rep_prod_ajustado / _stg alineadas con Datos_conciliados_of
    EXEC inventar_SpcHidr.sp_rep_prod_sync_schema;

    DECLARE @periodo TABLE (caso_id INT, fecha_inicio DATE, fecha_fin DATE);
    INSERT INTO @periodo (caso_id, fecha_inicio, fecha_fin)
    EXEC inventar_SpcHidr.sp_rep_get_periodo_caso @caso_id = @caso_id;

    SELECT TOP 1 @fecha_ini = fecha_inicio, @fecha_fin = fecha_fin FROM @periodo;

    IF @fecha_ini IS NULL OR @fecha_fin IS NULL
        THROW 50020, 'No se pudo obtener el período del caso (sp_rep_get_periodo_caso vacío).', 1;

    EXEC inventar_SpcHidr.sp_rep_log_start
        @run_id = @run_id, @caso_id = @caso_id, @fecha_ini = @fecha_ini, @fecha_fin = @fecha_fin;

    -- Targets SIEMPRE desde el control oficial vigente en DEV_SIIR (ver SP anterior)
    EXEC inventar_SpcHidr.sp_rep_build_targets_caso @caso_id = @caso_id;

    -- Resultset 1: metadata del run
    SELECT @run_id AS run_id, @caso_id AS caso_id, @fecha_ini AS fecha_inicio, @fecha_fin AS fecha_fin;

    -- Resultset 2: targets ya construidos
    SELECT target_code, target_value
    FROM inventar_SpcHidr.rep_prod_targets
    WHERE caso_id = @caso_id;
END

-- ============================================================
-- CONDUCTOR 2: todo lo posterior al staging (Python ya escribió rep_prod_ajustado_stg)
-- ============================================================
CREATE   PROCEDURE inventar_SpcHidr.sp_rep_conductor_post_ajuste
    @run_id UNIQUEIDENTIFIER,
    @ok BIT,
    @mensaje NVARCHAR(2000) = NULL,
    @totales_json NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ok = 1
    BEGIN
        EXEC inventar_SpcHidr.sp_rep_merge_ajustado_dyn @run_id = @run_id;
    END

    EXEC inventar_SpcHidr.sp_rep_log_end
        @run_id = @run_id, @ok = @ok, @mensaje = @mensaje, @totales_json = @totales_json;
END
